window.UMMAHTI_LIBRARY={"source":"Ummahti Quran app: feature/duas and data/reflectionlibrary (published entries only)","collections":["Hardship & distress","Anxiety & sorrow","Illness & healing","Forgiveness & repentance","Protection & refuge","Family","Provision & debt","Travel","Sleep & waking","Everyday remembrance","Guidance & knowledge"],"duas":[{"id":"dua_distress_yunus","k":0,"t":"When you feel trapped and out of options","m":null,"o":"The Qur’an records this supplication. No source sets a time or a number of repetitions for it, so it may be said whenever you wish.","q":[21,87,87],"ar":null,"tr":"La ilaha illa anta, subhanaka inni kuntu mina z-zalimin","src":null},{"id":"dua_burden_baqarah","k":0,"t":"When more has been asked of you than you can carry","m":null,"o":"The Qur’an records this supplication. No source sets a time or a number of repetitions for it, so it may be said whenever you wish.","q":[2,286,286],"ar":null,"tr":"Rabbana la tuhammilna ma la taqata lana bih, wa'fu 'anna waghfir lana warhamna","src":null},{"id":"dua_sufficiency_of_allah","k":0,"t":"When you are afraid, or outmatched","m":null,"o":"The Qur’an records this supplication. No source sets a time or a number of repetitions for it, so it may be said whenever you wish.","q":[3,173,173],"ar":null,"tr":"Hasbunallahu wa ni'ma l-wakil","src":null},{"id":"dua_affliction_ayyub","k":2,"t":"When an affliction has gone on a long time","m":null,"o":"The Qur’an records this supplication. No source sets a time or a number of repetitions for it, so it may be said whenever you wish.","q":[21,83,83],"ar":null,"tr":"Anni massaniya d-durru wa anta arhamu r-rahimin","src":null},{"id":"dua_ease_musa","k":10,"t":"Before something difficult you have to face","m":null,"o":"The Qur’an records this supplication. No source sets a time or a number of repetitions for it, so it may be said whenever you wish.","q":[20,25,28],"ar":null,"tr":"Rabbi shrah li sadri, wa yassir li amri, wahlul 'uqdatan min lisani, yafqahu qawli","src":null},{"id":"dua_turning_back","k":3,"t":"When you have wronged yourself and want to return","m":null,"o":"The Qur’an records this supplication. No source sets a time or a number of repetitions for it, so it may be said whenever you wish.","q":[7,23,23],"ar":null,"tr":"Rabbana zalamna anfusana wa in lam taghfir lana wa tarhamna lanakunanna mina l-khasirin","src":null},{"id":"dua_firm_heart","k":10,"t":"When doubt unsettles your heart","m":null,"o":"The Qur’an records this supplication. No source sets a time or a number of repetitions for it, so it may be said whenever you wish.","q":[3,8,8],"ar":null,"tr":"Rabbana la tuzigh qulubana ba'da idh hadaytana wa hab lana min ladunka rahmah, innaka anta l-Wahhab","src":null},{"id":"dua_increase_knowledge","k":10,"t":"Before studying, and whenever you seek knowledge","m":null,"o":"The Qur’an records this supplication. No source sets a time or a number of repetitions for it, so it may be said whenever you wish.","q":[20,114,114],"ar":null,"tr":"Rabbi zidni 'ilma","src":null},{"id":"dua_righteous_family","k":5,"t":"For a righteous spouse and children","m":null,"o":"The Qur’an records this supplication. No source sets a time or a number of repetitions for it, so it may be said whenever you wish.","q":[25,74,74],"ar":null,"tr":"Rabbana hab lana min azwajina wa dhurriyyatina qurrata a'yunin waj'alna lil-muttaqina imama","src":null},{"id":"dua_mercy_for_parents","k":5,"t":"For your parents, living or passed","m":null,"o":"The Qur’an records this supplication. No source sets a time or a number of repetitions for it, so it may be said whenever you wish.","q":[17,24,24],"ar":null,"tr":"Rabbi rhamhuma kama rabbayani saghira","src":null},{"id":"dua_good_in_both_worlds","k":9,"t":"For good in this life and the next","m":null,"o":"The Qur’an records this supplication. No source sets a time or a number of repetitions for it, so it may be said whenever you wish.","q":[2,201,201],"ar":null,"tr":"Rabbana atina fi d-dunya hasanatan wa fi l-akhirati hasanatan wa qina 'adhaba n-nar","src":null},{"id":"dua_ayat_al_kursi_night","k":8,"t":"Before you sleep","m":null,"o":"Reciting Ayat al-Kursi before sleeping is reported in Sahih al-Bukhari 3275.","q":[2,255,255],"ar":null,"tr":null,"src":null},{"id":"dua_worry_and_debt","k":1,"t":"When worry, weakness or debt is weighing on you","m":"O Allah, I seek refuge in You from worry and grief, from incapacity and laziness, from miserliness and cowardice, from the burden of debt and from being overpowered by others.","o":"Reported in Sahih al-Bukhari 6363 as a supplication the Prophet ﷺ used to say. No number of repetitions is reported with it.","q":null,"ar":"اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ، وَالْعَجْزِ وَالْكَسَلِ، وَالْبُخْلِ وَالْجُبْنِ، وَضَلَعِ الدَّيْنِ وَغَلَبَةِ الرِّجَالِ","tr":"Allahumma inni a'udhu bika mina l-hammi wa l-hazan, wa l-'ajzi wa l-kasal, wa l-bukhli wa l-jubn, wa dala'i d-dayni wa ghalabati r-rijal","src":{"c":"Sahih al-Bukhari","r":"6363","u":"https://sunnah.com/bukhari:6363","g":"Sahih"}},{"id":"dua_sayyid_al_istighfar","k":3,"t":"When you turn back to Allah and ask to be forgiven","m":"O Allah, You are my Lord; there is no god but You. You created me and I am Your servant. I keep to Your covenant and Your promise as far as I am able. I seek refuge in You from the harm of what I have done. I acknowledge Your favour upon me, and I acknowledge my sin, so forgive me, for none forgives sins but You.","o":"Reported in Sahih al-Bukhari 6306, where the Prophet ﷺ taught it as the finest way of asking Allah for forgiveness.","q":null,"ar":"اللَّهُمَّ أَنْتَ رَبِّي لَا إِلَهَ إِلَّا أَنْتَ، خَلَقْتَنِي وَأَنَا عَبْدُكَ، وَأَنَا عَلَى عَهْدِكَ وَوَعْدِكَ مَا اسْتَطَعْتُ، أَعُوذُ بِكَ مِنْ شَرِّ مَا صَنَعْتُ، أَبُوءُ لَكَ بِنِعْمَتِكَ عَلَيَّ، وَأَبُوءُ لَكَ بِذَنْبِي فَاغْفِرْ لِي، فَإِنَّهُ لَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ","tr":"Allahumma anta Rabbi, la ilaha illa anta, khalaqtani wa ana 'abduk, wa ana 'ala 'ahdika wa wa'dika ma stata't. A'udhu bika min sharri ma sana't. Abu'u laka bi ni'matika 'alayya, wa abu'u laka bi dhanbi faghfir li, fa innahu la yaghfiru dh-dhunuba illa ant","src":{"c":"Sahih al-Bukhari","r":"6306","u":"https://sunnah.com/bukhari:6306","g":"Sahih"}},{"id":"dua_on_calamity","k":1,"t":"When a loss or a calamity strikes","m":"O Allah, reward me in my affliction, and give me something better than it in its place.","o":"Reported in Sahih Muslim 918a as said when a calamity strikes, alongside the words the Qur’an teaches at 2:156.","q":null,"ar":"اللَّهُمَّ أْجُرْنِي فِي مُصِيبَتِي، وَأَخْلِفْ لِي خَيْرًا مِنْهَا","tr":"Allahumma'jurni fi musibati, wakhluf li khayran minha","src":{"c":"Sahih Muslim","r":"918a","u":"https://sunnah.com/muslim:918a","g":"Sahih"}},{"id":"dua_distress_supplication","k":0,"t":"When something is pressing on you","m":"There is no god but Allah, the Great, the Forbearing. There is no god but Allah, Lord of the Magnificent Throne. There is no god but Allah, Lord of the heavens and Lord of the earth and Lord of the Noble Throne.","o":"Reported as said at a time of distress.","q":null,"ar":"لَا إِلَهَ إِلَّا اللَّهُ الْعَظِيمُ الْحَلِيمُ، لَا إِلَهَ إِلَّا اللَّهُ رَبُّ الْعَرْشِ الْعَظِيمِ، لَا إِلَهَ إِلَّا اللَّهُ رَبُّ السَّمَاوَاتِ وَرَبُّ الْأَرْضِ وَرَبُّ الْعَرْشِ الْكَرِيمِ","tr":"La ilaha illa Allahu l-'Azimu l-Halim, la ilaha illa Allahu Rabbu l-'arshi l-'azim, la ilaha illa Allahu Rabbu s-samawati wa Rabbu l-ardi wa Rabbu l-'arshi l-karim","src":{"c":"Sahih Muslim","r":"2730a","u":"https://sunnah.com/muslim:2730a","g":"Sahih"}},{"id":"dua_hope_in_mercy","k":0,"t":"When you cannot manage on your own","m":"O Allah, it is Your mercy I hope for. Do not leave me to myself for the blink of an eye. Put right all of my affairs. There is no god but You.","o":"Reported as said at a time of distress.","q":null,"ar":"اللَّهُمَّ رَحْمَتَكَ أَرْجُو فَلَا تَكِلْنِي إِلَى نَفْسِي طَرْفَةَ عَيْنٍ، وَأَصْلِحْ لِي شَأْنِي كُلَّهُ، لَا إِلَهَ إِلَّا أَنْتَ","tr":"Allahumma rahmataka arju fa la takilni ila nafsi tarfata 'ayn, wa aslih li sha'ni kullah, la ilaha illa ant","src":{"c":"Sunan Abi Dawud","r":"5090","u":"https://sunnah.com/abudawud:5090","g":"Hasan in chain (per al-Albani)"}},{"id":"dua_allah_is_my_lord","k":0,"t":"A few words to hold on to","m":"Allah, Allah is my Lord. I associate nothing with Him.","o":"Reported as said at a time of distress.","q":null,"ar":"اللَّهُ اللَّهُ رَبِّي لَا أُشْرِكُ بِهِ شَيْئًا","tr":"Allahu Allahu Rabbi la ushriku bihi shay'a","src":{"c":"Sunan Abi Dawud","r":"1525","u":"https://sunnah.com/abudawud:1525","g":"Sahih (per al-Albani)"}},{"id":"dua_shield_against_them","k":0,"t":"When you are afraid of people","m":"O Allah, we place You before them, and we seek refuge in You from their evil.","o":"Reported as said when he ﷺ feared a group of people.","q":null,"ar":"اللَّهُمَّ إِنَّا نَجْعَلُكَ فِي نُحُورِهِمْ، وَنَعُوذُ بِكَ مِنْ شُرُورِهِمْ","tr":"Allahumma inna naj'aluka fi nuhurihim, wa na'udhu bika min shururihim","src":{"c":"Sunan Abi Dawud","r":"1537","u":"https://sunnah.com/abudawud:1537","g":"Sahih (per al-Albani)"}},{"id":"dua_decree_of_allah","k":0,"t":"When something has already gone wrong","m":"Allah decreed it, and He did what He willed.","o":"Reported as what to say when something has gone wrong, in place of \"if only\".","q":null,"ar":"قَدَّرَ اللَّهُ وَمَا شَاءَ فَعَلَ","tr":"Qaddara Allahu wa ma sha'a fa'al","src":{"c":"Sahih Muslim","r":"2664","u":"https://sunnah.com/muslim:2664","g":"Sahih"}},{"id":"dua_no_harm_purification","k":2,"t":"What to say to someone who is ill","m":"No harm. A cleansing, if Allah wills.","o":"Reported as said when visiting someone who is unwell.","q":null,"ar":"لَا بَأْسَ، طَهُورٌ إِنْ شَاءَ اللَّهُ","tr":"La ba'sa, tahurun in sha'a Allah","src":{"c":"Sahih al-Bukhari","r":"5656","u":"https://sunnah.com/bukhari:5656","g":"Sahih"}},{"id":"dua_asking_for_healing","k":2,"t":"Asking for someone to be made well","m":"I ask Allah the Great, Lord of the Magnificent Throne, to make you well.","o":"Reported as said when visiting someone who is unwell.","q":null,"ar":"أَسْأَلُ اللَّهَ الْعَظِيمَ، رَبَّ الْعَرْشِ الْعَظِيمِ، أَنْ يَشْفِيَكَ","tr":"As'alu Allaha l-'Azim, Rabba l-'arshi l-'azim, an yashfiyak","src":{"c":"Sunan Abi Dawud","r":"3106","u":"https://sunnah.com/abudawud:3106","g":"Sahih (per al-Albani)"}},{"id":"dua_pain_in_the_body","k":2,"t":"When something in your body hurts","m":"I seek refuge in Allah and in His power from the harm of what I feel and what I fear.","o":"Reported as said with your hand on the place that hurts, after saying \"In the name of Allah\" three times.","q":null,"ar":"أَعُوذُ بِاللَّهِ وَقُدْرَتِهِ مِنْ شَرِّ مَا أَجِدُ وَأُحَاذِرُ","tr":"A'udhu billahi wa qudratihi min sharri ma ajidu wa uhadhir","src":{"c":"Sahih Muslim","r":"2202","u":"https://sunnah.com/muslim:2202","g":"Sahih"}},{"id":"dua_gathering_expiation","k":3,"t":"On getting up from a gathering","m":"Glory be to You, O Allah, and praise. I bear witness that there is no god but You. I ask Your forgiveness and I turn to You.","o":"Reported as said on rising from a gathering.","q":null,"ar":"سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا أَنْتَ، أَسْتَغْفِرُكَ وَأَتُوبُ إِلَيْكَ","tr":"Subhanaka Allahumma wa bihamdik, ash-hadu an la ilaha illa ant, astaghfiruka wa atubu ilayk","src":{"c":"Sunan Abi Dawud","r":"4859","u":"https://sunnah.com/abudawud:4859","g":"Hasan Sahih (per al-Albani)"}},{"id":"dua_istighfar_of_the_living","k":3,"t":"Asking to be forgiven","m":"I ask forgiveness of Allah the Great, besides whom there is no god, the Living, the Sustainer, and I turn to Him.","o":"May be said at any time. The source names no particular occasion.","q":null,"ar":"أَسْتَغْفِرُ اللَّهَ الْعَظِيمَ الَّذِي لَا إِلَهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ وَأَتُوبُ إِلَيْهِ","tr":"Astaghfiru Allaha l-'Azima lladhi la ilaha illa huwa l-Hayyu l-Qayyumu wa atubu ilayh","src":{"c":"Jami' at-Tirmidhi","r":"3577","u":"https://sunnah.com/tirmidhi:3577","g":"Hasan (per Darussalam)"}},{"id":"dua_hundred_times_in_a_sitting","k":3,"t":"The one he ﷺ said most often","m":"My Lord, forgive me and accept my turning back to You. You are the Ever-Relenting, the Forgiving.","o":"Reported as said by him ﷺ within a single sitting.","q":null,"ar":"رَبِّ اغْفِرْ لِي وَتُبْ عَلَيَّ إِنَّكَ أَنْتَ التَّوَّابُ الْغَفُورُ","tr":"Rabbi ghfir li wa tub 'alayya innaka anta t-Tawwabu l-Ghafur","src":{"c":"Jami' at-Tirmidhi","r":"3434","u":"https://sunnah.com/tirmidhi:3434","g":"Sahih (per Darussalam)"}},{"id":"dua_subhanallahi_wa_bihamdih","k":3,"t":"A hundred times in a day","m":"Glory be to Allah, and praise be to Him.","o":"Reported as said in the course of a day.","q":null,"ar":"سُبْحَانَ اللَّهِ وَبِحَمْدِهِ","tr":"Subhana Allahi wa bihamdih","src":{"c":"Sahih Muslim","r":"2691","u":"https://sunnah.com/muslim:2691","g":"Sahih"}},{"id":"dua_by_you_we_enter_the_morning","k":4,"t":"Opening the day","m":"O Allah, by You we enter the morning and by You we enter the evening. By You we live and by You we die, and to You is the rising.","o":"Reported as said in the morning and again in the evening.","q":null,"ar":"اللَّهُمَّ بِكَ أَصْبَحْنَا، وَبِكَ أَمْسَيْنَا، وَبِكَ نَحْيَا، وَبِكَ نَمُوتُ، وَإِلَيْكَ النُّشُورُ","tr":"Allahumma bika asbahna, wa bika amsayna, wa bika nahya, wa bika namut, wa ilayka n-nushur","src":{"c":"Sunan Abi Dawud","r":"5068","u":"https://sunnah.com/abudawud:5068","g":"Sahih (per al-Albani)"}},{"id":"dua_pardon_and_wellbeing","k":4,"t":"Asking to be kept safe on every side","m":"O Allah, I ask You for well-being in this world and the next. O Allah, I ask You for pardon and for well-being in my religion, my worldly life, my family and my wealth. O Allah, cover what I would not have seen and settle what frightens me. O Allah, guard me from in front of me and behind me, from my right and my left and from above me, and I seek refuge in Your greatness from being taken from beneath me.","o":"Reported as said in the morning and again in the evening.","q":null,"ar":"اللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَافِيَةَ فِي الدُّنْيَا وَالْآخِرَةِ، اللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَفْوَ وَالْعَافِيَةَ فِي دِينِي وَدُنْيَايَ وَأَهْلِي وَمَالِي، اللَّهُمَّ اسْتُرْ عَوْرَاتِي وَآمِنْ رَوْعَاتِي، اللَّهُمَّ احْفَظْنِي مِنْ بَيْنِ يَدَيَّ وَمِنْ خَلْفِي وَعَنْ يَمِينِي وَعَنْ شِمَالِي وَمِنْ فَوْقِي، وَأَعُوذُ بِعَظَمَتِكَ أَنْ أُغْتَالَ مِنْ تَحْتِي","tr":"Allahumma inni as'aluka l-'afiyata fi d-dunya wa l-akhirah, Allahumma inni as'aluka l-'afwa wa l-'afiyata fi dini wa dunyaya wa ahli wa mali, Allahumma stur 'awrati wa amin raw'ati, Allahumma hfazni min bayni yadayya wa min khalfi wa 'an yamini wa 'an shimali wa min fawqi, wa a'udhu bi 'azamatika an ughtala min tahti","src":{"c":"Sunan Abi Dawud","r":"5074","u":"https://sunnah.com/abudawud:5074","g":"Sahih (per al-Albani)"}},{"id":"dua_protecting_children","k":5,"t":"Placing a child in Allah's keeping","m":"I place you both in the keeping of the perfect words of Allah, from every devil and every crawling thing, and from every eye that harms.","o":"Reported as said by him ﷺ over al-Hasan and al-Husayn.","q":null,"ar":"أُعِيذُكُمَا بِكَلِمَاتِ اللَّهِ التَّامَّةِ، مِنْ كُلِّ شَيْطَانٍ وَهَامَّةٍ، وَمِنْ كُلِّ عَيْنٍ لَامَّةٍ","tr":"U'idhukuma bi kalimati Allahi t-tammah, min kulli shaytanin wa hammah, wa min kulli 'aynin lammah","src":{"c":"Jami' at-Tirmidhi","r":"2060","u":"https://sunnah.com/tirmidhi:2060","g":"Sahih (per Darussalam)"}},{"id":"dua_blessing_the_newlywed","k":5,"t":"What to say at a wedding","m":"May Allah bless you, and send blessings upon you, and bring you together in what is good.","o":"Reported as said to someone who has just married.","q":null,"ar":"بَارَكَ اللَّهُ لَكَ، وَبَارَكَ عَلَيْكَ، وَجَمَعَ بَيْنَكُمَا فِي خَيْرٍ","tr":"Baraka Allahu lak, wa baraka 'alayk, wa jama'a baynakuma fi khayr","src":{"c":"Sunan Abi Dawud","r":"2130","u":"https://sunnah.com/abudawud:2130","g":"Sahih (per al-Albani)"}},{"id":"dua_asking_for_her_good","k":5,"t":"At the start of a marriage","m":"O Allah, I ask You for the good in her, and for the good of what You have made her inclined towards, and I seek refuge in You from the harm in her, and from the harm of what You have made her inclined towards.","o":"Reported as said at the start of a marriage.","q":null,"ar":"اللَّهُمَّ إِنِّي أَسْأَلُكَ خَيْرَهَا، وَخَيْرَ مَا جَبَلْتَهَا عَلَيْهِ، وَأَعُوذُ بِكَ مِنْ شَرِّهَا، وَشَرِّ مَا جَبَلْتَهَا عَلَيْهِ","tr":"Allahumma inni as'aluka khayraha, wa khayra ma jabaltaha 'alayh, wa a'udhu bika min sharriha, wa sharri ma jabaltaha 'alayh","src":{"c":"Sunan Abi Dawud","r":"2160","u":"https://sunnah.com/abudawud:2160","g":"Hasan (per al-Albani)"}},{"id":"dua_suffice_me_with_the_lawful","k":6,"t":"When a debt will not settle","m":"O Allah, let what You have made lawful be enough for me instead of what You have forbidden, and by Your bounty make me need no one but You.","o":"Reported as taught for a debt that will not settle.","q":null,"ar":"اللَّهُمَّ اكْفِنِي بِحَلَالِكَ عَنْ حَرَامِكَ، وَأَغْنِنِي بِفَضْلِكَ عَمَّنْ سِوَاكَ","tr":"Allahumma kfini bi halalika 'an haramik, wa aghnini bi fadlika 'amman siwak","src":{"c":"Jami' at-Tirmidhi","r":"3563","u":"https://sunnah.com/tirmidhi:3563","g":"Hasan (per Darussalam)"}},{"id":"dua_thanking_the_lender","k":6,"t":"When you have paid someone back","m":"May Allah bless you in your family and your wealth. The repayment of a loan is thanks and the returning of it.","o":"Reported as said to someone who lent to you, once the loan is returned.","q":null,"ar":"بَارَكَ اللَّهُ لَكَ فِي أَهْلِكَ وَمَالِكَ، إِنَّمَا جَزَاءُ السَّلَفِ الْحَمْدُ وَالْأَدَاءُ","tr":"Baraka Allahu laka fi ahlika wa malik, innama jaza'u s-salafi l-hamdu wa l-ada'","src":{"c":"Sunan an-Nasa'i","r":"4683","u":"https://sunnah.com/nasai:4683","g":"Hasan (per Darussalam)"}},{"id":"dua_entrusting_the_traveller","k":7,"t":"Seeing somebody off","m":"I place in Allah's keeping your religion, what has been entrusted to you, and the ends of your deeds.","o":"Reported as said to somebody who is setting out.","q":null,"ar":"أَسْتَوْدِعُ اللَّهَ دِينَكَ وَأَمَانَتَكَ، وَخَوَاتِيمَ عَمَلِكَ","tr":"Astawdi'u Allaha dinaka wa amanatak, wa khawatima 'amalik","src":{"c":"Sunan Abi Dawud","r":"2600","u":"https://sunnah.com/abudawud:2600","g":"Sahih (per al-Albani)"}},{"id":"dua_stopping_somewhere","k":7,"t":"Stopping somewhere new","m":"I seek refuge in the perfect words of Allah from the harm of what He has created.","o":"Reported as said on stopping or staying somewhere.","q":null,"ar":"أَعُوذُ بِكَلِمَاتِ اللَّهِ التَّامَّاتِ مِنْ شَرِّ مَا خَلَقَ","tr":"A'udhu bi kalimati Allahi t-tammati min sharri ma khalaq","src":{"c":"Sahih Muslim","r":"2708b","u":"https://sunnah.com/muslim:2708b","g":"Sahih"}},{"id":"dua_praise_on_waking","k":8,"t":"Opening your eyes","m":"Praise be to Allah, who gave us life after having taken it from us, and to Him is the rising.","o":"Reported as said on waking.","q":null,"ar":"الْحَمْدُ لِلَّهِ الَّذِي أَحْيَانَا بَعْدَ مَا أَمَاتَنَا وَإِلَيْهِ النُّشُورُ","tr":"Al-hamdu lillahi lladhi ahyana ba'da ma amatana wa ilayhi n-nushur","src":{"c":"Sahih al-Bukhari","r":"7394","u":"https://sunnah.com/bukhari:7394","g":"Sahih"}},{"id":"dua_soul_returned","k":8,"t":"Waking up well","m":"Praise be to Allah, who kept my body sound, and returned my soul to me, and permitted me to remember Him.","o":"Reported as said on waking.","q":null,"ar":"الْحَمْدُ لِلَّهِ الَّذِي عَافَانِي فِي جَسَدِي وَرَدَّ عَلَيَّ رُوحِي وَأَذِنَ لِي بِذِكْرِهِ","tr":"Al-hamdu lillahi lladhi 'afani fi jasadi wa radda 'alayya ruhi wa adhina li bi dhikrih","src":{"c":"Jami' at-Tirmidhi","r":"3401","u":"https://sunnah.com/tirmidhi:3401","g":"Sahih (per Darussalam)"}},{"id":"dua_laying_down_my_side","k":8,"t":"Lying down for the night","m":"In Your name, my Lord, I lay down my side, and by You I raise it again. If You take my soul, have mercy on it; and if You send it back, then guard it as You guard Your righteous servants.","o":"Reported as said on lying down to sleep.","q":null,"ar":"بِاسْمِكَ رَبِّي وَضَعْتُ جَنْبِي، وَبِكَ أَرْفَعُهُ، فَإِنْ أَمْسَكْتَ نَفْسِي فَارْحَمْهَا، وَإِنْ أَرْسَلْتَهَا فَاحْفَظْهَا بِمَا تَحْفَظُ بِهِ عِبَادَكَ الصَّالِحِينَ","tr":"Bismika Rabbi wada'tu janbi, wa bika arfa'uh, fa in amsakta nafsi farhamha, wa in arsaltaha fahfazha bima tahfazu bihi 'ibadaka s-salihin","src":{"c":"Sahih al-Bukhari","r":"6320","u":"https://sunnah.com/bukhari:6320","g":"Sahih"}},{"id":"dua_in_your_name_i_die_and_live","k":8,"t":"Two lines before sleep","m":"In Your name, O Allah, I die and I live.","o":"Reported as said on lying down to sleep.","q":null,"ar":"بِاسْمِكَ اللَّهُمَّ أَمُوتُ وَأَحْيَا","tr":"Bismika Allahumma amutu wa ahya","src":{"c":"Sahih al-Bukhari","r":"6324","u":"https://sunnah.com/bukhari:6324","g":"Sahih"}},{"id":"dua_fed_and_sheltered","k":8,"t":"Counting the day's mercies","m":"Praise be to Allah, who fed us and gave us drink, and was enough for us, and gave us shelter. How many are there with no one to suffice them and nowhere to shelter.","o":"Reported as said on lying down to sleep.","q":null,"ar":"الْحَمْدُ لِلَّهِ الَّذِي أَطْعَمَنَا وَسَقَانَا، وَكَفَانَا، وَآوَانَا، فَكَمْ مِمَّنْ لَا كَافِيَ لَهُ وَلَا مُؤْوِيَ","tr":"Al-hamdu lillahi lladhi at'amana wa saqana, wa kafana, wa awana, fakam mimman la kafiya lahu wa la mu'wi","src":{"c":"Sahih Muslim","r":"2715","u":"https://sunnah.com/muslim:2715","g":"Sahih"}},{"id":"dua_after_ablution","k":9,"t":"Finishing your wudu","m":"I bear witness that there is no god but Allah alone. He has no partner. And I bear witness that Muhammad is His servant and His Messenger.","o":"Reported as said on completing ablution.","q":null,"ar":"أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ","tr":"Ash-hadu an la ilaha illa Allahu wahdahu la sharika lah, wa ash-hadu anna Muhammadan 'abduhu wa rasuluh","src":{"c":"Sahih Muslim","r":"234b","u":"https://sunnah.com/muslim:234b","g":"Sahih"}},{"id":"dua_leaving_the_home","k":9,"t":"Going out of the door","m":"In the name of Allah. I have placed my trust in Allah. There is no strength and no power except by Allah.","o":"Reported as said on leaving the house.","q":null,"ar":"بِسْمِ اللَّهِ، تَوَكَّلْتُ عَلَى اللَّهِ، وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ","tr":"Bismillah, tawakkaltu 'ala Allah, wa la hawla wa la quwwata illa billah","src":{"c":"Sunan Abi Dawud","r":"5095","u":"https://sunnah.com/abudawud:5095","g":"Sahih (per al-Albani)"}},{"id":"dua_breaking_the_fast","k":9,"t":"Breaking your fast","m":"The thirst has gone, the veins are moistened, and the reward is confirmed, if Allah wills.","o":"Reported as said by him ﷺ on breaking his fast.","q":null,"ar":"ذَهَبَ الظَّمَأُ، وَابْتَلَّتِ الْعُرُوقُ، وَثَبَتَ الْأَجْرُ إِنْ شَاءَ اللَّهُ","tr":"Dhahaba z-zama'u, wa btallati l-'uruq, wa thabata l-ajru in sha'a Allah","src":{"c":"Sunan Abi Dawud","r":"2357","u":"https://sunnah.com/abudawud:2357","g":"Hasan (per al-Albani)"}},{"id":"dua_after_the_meal","k":9,"t":"After you have eaten","m":"Praise be to Allah, who fed me this and provided it for me, with no strength or power of my own.","o":"Reported as said after eating.","q":null,"ar":"الْحَمْدُ لِلَّهِ الَّذِي أَطْعَمَنِي هَذَا وَرَزَقَنِيهِ مِنْ غَيْرِ حَوْلٍ مِنِّي وَلَا قُوَّةٍ","tr":"Al-hamdu lillahi lladhi at'amani hadha wa razaqanih min ghayri hawlin minni wa la quwwah","src":{"c":"Jami' at-Tirmidhi","r":"3458","u":"https://sunnah.com/tirmidhi:3458","g":"Hasan (per Darussalam)"}},{"id":"dua_when_angry","k":9,"t":"When your temper rises","m":"I seek refuge in Allah from the devil, the outcast.","o":"Reported as what to say when anger takes hold.","q":null,"ar":"أَعُوذُ بِاللَّهِ مِنَ الشَّيْطَانِ الرَّجِيمِ","tr":"A'udhu billahi mina sh-shaytani r-rajim","src":{"c":"Sahih al-Bukhari","r":"6115","u":"https://sunnah.com/bukhari:6115","g":"Sahih"}},{"id":"dua_istikharah","k":10,"t":"When you cannot decide","m":"O Allah, I ask You to choose for me by Your knowledge, and I ask You for the power to act by Your power, and I ask You of Your great bounty. For You are able and I am not, and You know and I do not, and You are the Knower of all that is hidden. O Allah, if You know that this matter is good for me in my religion, my living and the outcome of my affairs, then decree it for me and make it easy for me, and then bless me in it. And if You know that this matter is bad for me in my religion, my living and the outcome of my affairs, then turn it away from me and turn me away from it, and decree for me what is good wherever it is, and then make me content with it.","o":"Reported as taught for any matter you are deciding, after praying two units of prayer outside the obligatory ones. Name the matter where the words say \"this matter\".","q":null,"ar":"اللَّهُمَّ إِنِّي أَسْتَخِيرُكَ بِعِلْمِكَ، وَأَسْتَقْدِرُكَ بِقُدْرَتِكَ، وَأَسْأَلُكَ مِنْ فَضْلِكَ الْعَظِيمِ، فَإِنَّكَ تَقْدِرُ وَلَا أَقْدِرُ، وَتَعْلَمُ وَلَا أَعْلَمُ، وَأَنْتَ عَلَّامُ الْغُيُوبِ، اللَّهُمَّ إِنْ كُنْتَ تَعْلَمُ أَنَّ هَذَا الْأَمْرَ خَيْرٌ لِي فِي دِينِي وَمَعَاشِي وَعَاقِبَةِ أَمْرِي فَاقْدُرْهُ لِي وَيَسِّرْهُ لِي ثُمَّ بَارِكْ لِي فِيهِ، وَإِنْ كُنْتَ تَعْلَمُ أَنَّ هَذَا الْأَمْرَ شَرٌّ لِي فِي دِينِي وَمَعَاشِي وَعَاقِبَةِ أَمْرِي فَاصْرِفْهُ عَنِّي وَاصْرِفْنِي عَنْهُ، وَاقْدُرْ لِي الْخَيْرَ حَيْثُ كَانَ ثُمَّ أَرْضِنِي بِهِ","tr":"Allahumma inni astakhiruka bi 'ilmik, wa astaqdiruka bi qudratik, wa as'aluka min fadlika l-'azim, fa innaka taqdiru wa la aqdir, wa ta'lamu wa la a'lam, wa anta 'allamu l-ghuyub. Allahumma in kunta ta'lamu anna hadha l-amra khayrun li fi dini wa ma'ashi wa 'aqibati amri faqdurhu li wa yassirhu li thumma barik li fih. Wa in kunta ta'lamu anna hadha l-amra sharrun li fi dini wa ma'ashi wa 'aqibati amri fasrifhu 'anni wasrifni 'anh, waqdur li l-khayra haythu kana thumma ardini bih","src":{"c":"Sahih al-Bukhari","r":"1166","u":"https://sunnah.com/bukhari:1166","g":"Sahih"}},{"id":"dua_setting_out_on_a_journey","k":7,"t":"Setting out on a journey","m":"Glory be to the One who has placed this at our service, when we could never have mastered it ourselves, and to our Lord we will surely return. O Allah, on this journey of ours we ask You for righteousness and mindfulness of You, and for deeds that please You. O Allah, make this journey easy for us and shorten its distance for us. O Allah, You are the Companion on the journey and the One who looks after the family left behind. O Allah, I seek refuge in You from the hardship of travel, from a distressing sight, and from an unhappy return to my wealth and my family.","o":"Reported as said by him ﷺ on mounting to set out on a journey, after saying Allahu akbar three times. On returning he said the same words, and added: we return, repenting, worshipping and praising our Lord.","q":null,"ar":"سُبْحَانَ الَّذِي سَخَّرَ لَنَا هَذَا وَمَا كُنَّا لَهُ مُقْرِنِينَ، وَإِنَّا إِلَى رَبِّنَا لَمُنْقَلِبُونَ، اللَّهُمَّ إِنَّا نَسْأَلُكَ فِي سَفَرِنَا هَذَا الْبِرَّ وَالتَّقْوَى، وَمِنَ الْعَمَلِ مَا تَرْضَى، اللَّهُمَّ هَوِّنْ عَلَيْنَا سَفَرَنَا هَذَا، وَاطْوِ عَنَّا بُعْدَهُ، اللَّهُمَّ أَنْتَ الصَّاحِبُ فِي السَّفَرِ، وَالْخَلِيفَةُ فِي الأَهْلِ، اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ وَعْثَاءِ السَّفَرِ، وَكَآبَةِ الْمَنْظَرِ، وَسُوءِ الْمُنْقَلَبِ فِي الْمَالِ وَالأَهْلِ","tr":"Subhana lladhi sakhkhara lana hadha wa ma kunna lahu muqrinin, wa inna ila Rabbina la-munqalibun. Allahumma inna nas'aluka fi safarina hadha l-birra wa t-taqwa, wa mina l-'amali ma tarda. Allahumma hawwin 'alayna safarana hadha, watwi 'anna bu'dah. Allahumma anta s-sahibu fi s-safar, wa l-khalifatu fi l-ahl. Allahumma inni a'udhu bika min wa'tha'i s-safar, wa ka'abati l-manzar, wa su'i l-munqalabi fi l-mali wa l-ahl","src":{"c":"Sahih Muslim","r":"1342","u":"https://sunnah.com/muslim:1342","g":"Sahih"}},{"id":"dua_entering_the_mosque","k":9,"t":"Entering the mosque","m":"O Allah, open for me the doors of Your mercy.","o":"Reported as taught for entering the mosque. The same narration teaches asking Allah for His bounty on leaving it.","q":null,"ar":"اللَّهُمَّ افْتَحْ لِي أَبْوَابَ رَحْمَتِكَ","tr":"Allahumma ftah li abwaba rahmatik","src":{"c":"Sahih Muslim","r":"713a","u":"https://sunnah.com/muslim:713a","g":"Sahih"}},{"id":"dua_laylat_al_qadr","k":3,"t":"On Laylat al-Qadr","m":"O Allah, You are the One who pardons, and You love to pardon, so pardon me.","o":"Reported as taught by him ﷺ to ‘A’ishah, who asked what to say if she came upon Laylat al-Qadr.","q":null,"ar":"اللَّهُمَّ إِنَّكَ عَفُوٌّ تُحِبُّ الْعَفْوَ فَاعْفُ عَنِّي","tr":"Allahumma innaka 'Afuwwun tuhibbu l-'afwa fa'fu 'anni","src":{"c":"Sunan Ibn Majah","r":"3850","u":"https://sunnah.com/ibnmajah:3850","g":"Sahih (per Darussalam)"}},{"id":"dua_after_the_adhan","k":9,"t":"After the call to prayer","m":"O Allah, Lord of this complete call and of the prayer about to be established, grant Muhammad al-Wasilah and the place of honour, and raise him to the praised station You have promised him.","o":"Reported as said on hearing the call to prayer.","q":null,"ar":"اللَّهُمَّ رَبَّ هَذِهِ الدَّعْوَةِ التَّامَّةِ وَالصَّلاَةِ الْقَائِمَةِ، آتِ مُحَمَّدًا الْوَسِيلَةَ وَالْفَضِيلَةَ، وَابْعَثْهُ مَقَامًا مَحْمُودًا الَّذِي وَعَدْتَهُ","tr":"Allahumma Rabba hadhihi d-da'wati t-tammah, wa s-salati l-qa'imah, ati Muhammadan al-wasilata wa l-fadilah, wab'ath-hu maqaman mahmudan alladhi wa'adtah","src":{"c":"Sahih al-Bukhari","r":"614","u":"https://sunnah.com/bukhari:614","g":"Sahih"}},{"id":"dua_after_the_prayer","k":9,"t":"On finishing the prayer","m":"O Allah, You are Peace and from You comes peace. Blessed are You, Possessor of Majesty and Honour.","o":"Reported as said by him ﷺ on finishing the prayer, after asking Allah’s forgiveness three times.","q":null,"ar":"اللَّهُمَّ أَنْتَ السَّلاَمُ وَمِنْكَ السَّلاَمُ، تَبَارَكْتَ ذَا الْجَلاَلِ وَالإِكْرَامِ","tr":"Allahumma anta s-salamu wa minka s-salam, tabarakta dha l-jalali wa l-ikram","src":{"c":"Sahih Muslim","r":"591","u":"https://sunnah.com/muslim:591","g":"Sahih"}},{"id":"dua_for_those_before_us","k":3,"t":"For those who have gone before us","m":null,"o":"The Qur’an records this supplication. No source sets a time or a number of repetitions for it, so it may be said whenever you wish.","q":[59,10,10],"ar":null,"tr":"Rabbana ghfir lana wa li-ikhwanina lladhina sabaquna bi-l-iman, wa la taj'al fi qulubina ghillan li-lladhina amanu, Rabbana innaka Ra'ufun Rahim","src":null},{"id":"dua_offspring_zakariyya","k":5,"t":"Asking Allah for a child","m":null,"o":"The Qur’an records this supplication. No source sets a time or a number of repetitions for it, so it may be said whenever you wish.","q":[3,38,38],"ar":null,"tr":"Rabbi hab li min ladunka dhurriyyatan tayyibah, innaka sami'u d-du'a'","src":null},{"id":"dua_gratitude_sulayman","k":9,"t":"Asking to be grateful","m":null,"o":"The Qur’an records this supplication. No source sets a time or a number of repetitions for it, so it may be said whenever you wish.","q":[27,19,19],"ar":null,"tr":"Rabbi awzi'ni an ashkura ni'mataka llati an'amta 'alayya wa 'ala walidayya wa an a'mala salihan tardah, wa adkhilni bi-rahmatika fi 'ibadika s-salihin","src":null}],"prophets":["MUSA","IBRAHIM","YUSUF","NUH","ADAM","YUNUS","AYYUB","MARYAM","ISA","DAWUD","SULAYMAN","YAQUB","SHUAYB","ZAKARIYYA","YAHYA","HUD","ISMAIL"],"reflections":[{"id":"musa_love_cast","t":"Loved Before He Knew It","b":"A basket on a river is not a plan any mother would choose. Allah tells Musa that He cast love upon him from Himself, and had him raised under His own eye. The current was never the one in charge.","th":[0],"p":0,"q":[20,39]},{"id":"musa_mother_river","t":"The Hardest Instruction","b":"She was told to put her child into the water, and told in the same breath not to fear and not to grieve. The obedience came first and the reassurance travelled with it. What are you being asked to let go of?","th":[0],"p":0,"q":[28,7]},{"id":"musa_mother_heart","t":"A Heart Held Together","b":"Her heart emptied of everything but him. The Quran says Allah bound it fast so that she would not give the secret away. Even the strength to stay silent was given to her, not summoned by her.","th":[0],"p":0,"q":[28,10]},{"id":"musa_untie_my_tongue","t":"He Asked for Room","b":"Sent to the most powerful man alive, Musa did not ask for power. He asked for a wider chest, an easier task, and a tongue that would not fail him. Ask for what the task actually needs.","th":[0],"p":0,"q":[20,25]},{"id":"musa_i_am_with_you","t":"Before He Even Arrived","b":"Musa and Harun said they feared Pharaoh would strike first. The answer was not a strategy but company: do not fear, I am with you both, hearing and seeing. The fear was not scolded. It was answered.","th":[0],"p":0,"q":[20,46]},{"id":"musa_sea_ahead","t":"Water Ahead, Army Behind","b":"His people counted the odds aloud and called capture certain. Musa corrected the arithmetic rather than the fear: my Lord is with me, He will guide me. The sea opened after that certainty, not before it.","th":[0],"p":0,"q":[26,62]},{"id":"musa_madyan_shade","t":"Poor, and Not Ashamed of It","b":"A stranger in Madyan with nothing to his name, he watered another household's flock first, then sat in the shade and told Allah he was in need of whatever good He might send down. Within the day he had work, shelter and a family.","th":[0],"p":0,"q":[28,24]},{"id":"musa_pray_for_my_remembrance","t":"Why the Prayer Exists","b":"The first thing said to Musa at the fire was not a mission. It was Allah naming Himself, then a command to establish prayer for His remembrance. Salah is not a task added to the day. It is the reason the day is yours.","th":[0],"p":0,"q":[20,14]},{"id":"musa_show_me","t":"The Question He Was Allowed to Ask","b":"He asked to see Him. The answer was no, and then a mountain crumbled at a glimpse and Musa fell unconscious. Not every refusal is a rebuke. Some are a mercy you could not have survived otherwise.","th":[0],"p":0,"q":[7,143]},{"id":"musa_hastened","t":"Early, Because He Wanted to Be","b":"Asked why he had left his people behind, Musa said they were close on his tracks, and that he had hurried on ahead to his Lord so that He would be pleased. Eagerness is its own act of worship.","th":[0],"p":0,"q":[20,84]},{"id":"musa_khidr_teach_me","t":"The Prophet Who Asked to Be a Student","b":"Musa had already spoken with Allah, and still he asked permission to follow a teacher so that he might be taught. Nobody outgrows being taught. Who could teach you something this month?","th":[0],"p":0,"q":[18,66]},{"id":"musa_tuwa_sandals","t":"Take Off Your Sandals","b":"Before the message and before the miracle came an instruction about his feet. He was standing in a sacred valley and needed to know it. Some places, and some moments, ask you to arrive differently.","th":[0],"p":0,"q":[20,12]},{"id":"musa_strengthen_arm_brother","t":"He Asked for His Brother","b":"Musa did not ask for a stronger arm. He asked for Harun beside him, and was told his arm would be strengthened through his brother. Help is not a lesser form of strength. It is often the form strength arrives in.","th":[0],"p":0,"q":[28,35]},{"id":"musa_you_are_our_protector","t":"After the Worst Week","b":"His people had done the one thing he had warned them against, and seventy of them lay struck down. Musa did not defend them. He called Allah their Protector, asked for forgiveness and mercy, and left it there.","th":[0],"p":0,"q":[7,155]},{"id":"musa_gentle_speech","t":"Speak to Him Gently","b":"The instruction concerning Pharaoh, a man who claimed divinity, was to speak to him with soft words in the hope that he might take heed. If that tyrant was owed gentleness, so is the person you are arguing with tonight.","th":[0],"p":0,"q":[20,44]},{"id":"ibrahim_satisfy_my_heart","t":"Not Doubt. Reassurance.","b":"He asked to be shown how the dead are given life. Asked whether he did not believe, he said that he did, but that his heart might be at rest. Wanting to feel it is not the same as failing to believe it.","th":[0],"p":1,"q":[2,260]},{"id":"ibrahim_star_moon_sun","t":"Nothing That Sets","b":"He watched a star, then a moon, then the sun, and let go of each as it went down. Then he turned his face to the One who originated the heavens and the earth. Whatever you have built your peace on, does it set?","th":[0],"p":1,"q":[6,79]},{"id":"ibrahim_fire_cool","t":"The Fire Was Not Put Out","b":"They built it, they threw him into it, and the command went to the fire itself: be coolness and peace. Sometimes what threatens you is not removed. It is simply told to stop burning.","th":[0],"p":1,"q":[21,69]},{"id":"ibrahim_dream_sacrifice","t":"He Told His Son First","b":"Ibrahim did not act on the dream alone. He told his son and asked what he saw in it, and the boy answered that he would be found patient. Two people carried it, and neither of them broke.","th":[0],"p":1,"q":[37,102]},{"id":"ibrahim_ask_for_righteous","t":"Most of a Lifetime of Asking","b":"The one request he made for himself, as the Quran records it, was for a righteous child. He waited decades. The delay was never a refusal, and the answer has outlived him by every generation since.","th":[0],"p":1,"q":[37,100]},{"id":"ibrahim_barren_valley","t":"A Valley With Nothing in It","b":"He left his family where nothing grew, and prayed that hearts would incline toward them and that they would be given fruits to eat. Millions circle that valley now. He could see none of it when he prayed.","th":[0],"p":1,"q":[14,37]},{"id":"ibrahim_establisher_of_prayer","t":"Make Me One Who Prays","b":"An old man at the end of a lifetime of obedience asks to be made someone who establishes prayer, and asks it for his descendants too. He never assumed consistency was something he already had.","th":[0],"p":1,"q":[14,40]},{"id":"ibrahim_accept_from_us","t":"Building, and Begging","b":"Raising the foundations of the House with his son, he did not admire the work. He asked Allah to accept it from them. Do the deed, then ask for it to be received. The second half is not optional.","th":[0],"p":1,"q":[2,127]},{"id":"ibrahim_mention_of_truth","t":"A Reputation He Did Not Build","b":"He asked for a truthful mention among those who would come later. Every prayer offered in Islam since has carried his name. He asked, and was answered in a currency he never handled himself.","th":[0],"p":1,"q":[26,84]},{"id":"ibrahim_a_nation_alone","t":"One Man, Counted as a Nation","b":"The Quran calls Ibrahim a nation in himself, devoutly obedient, inclining to truth. When you find yourself the only person in the room still holding the line, there is precedent for it.","th":[0],"p":1,"q":[16,120]},{"id":"ibrahim_excellent_pattern","t":"What He Made Clear","b":"The Quran offers Ibrahim as an example, and points specifically at how openly he separated himself from what his people worshipped. Clarity was the pattern being praised. Not hostility. Clarity.","th":[0],"p":1,"q":[60,4]},{"id":"ibrahim_forgiveness_for_father","t":"He Was Threatened. He Said Peace.","b":"His father promised to stone him and told him to leave for a long while. Ibrahim answered with peace and a promise to seek forgiveness for him. Refusing to return cruelty is a discipline, not a temperament.","th":[0],"p":1,"q":[19,47]},{"id":"yusuf_dream_eleven_stars","t":"Tell the Right People","b":"A boy saw eleven stars and the sun and the moon prostrating to him. The first instruction from his father was to keep it to himself. Not every good thing you are given is safe in every room.","th":[0],"p":2,"q":[12,4]},{"id":"yusuf_maadhallah","t":"Two Words in a Locked Room","b":"Doors bolted, no witnesses, everything arranged. What he said was that he sought refuge in Allah. He did not negotiate with her. He moved the matter out of his own hands immediately.","th":[0],"p":2,"q":[12,23]},{"id":"yusuf_prison_preferred","t":"He Chose the Cell","b":"He told Allah plainly that prison was dearer to him than what they were calling him to, and then admitted he could not turn away from them without help. The strength was asked for, never claimed.","th":[0],"p":2,"q":[12,33]},{"id":"yusuf_forgotten_in_prison","t":"Mention Me to Your Master","b":"He asked a fellow prisoner to remember him, and the man forgot, and years went by. He was not punished for asking. But the release, when it finally came, came from somewhere he had not asked.","th":[0],"p":2,"q":[12,42]},{"id":"yusuf_the_soul_commands","t":"He Did Not Trust Himself","b":"At the height of his vindication, Yusuf refused to declare himself innocent, saying the soul persistently urges evil except where his Lord shows mercy. The safest people are the ones who never assume they are safe.","th":[0],"p":2,"q":[12,53]},{"id":"yusuf_taqwa_and_sabr","t":"Fear Allah, and Hold On","b":"Recognised at last by the brothers who had thrown him down a well, he named the only two things that had carried him: mindfulness of Allah, and patience. Allah does not waste the reward of those who do good.","th":[0],"p":2,"q":[12,90]},{"id":"yusuf_no_blame_today","t":"The Sentence He Could Have Passed","b":"He had the power, the proof and the audience. What he said was that there would be no reproach upon them today. Forgiveness is loudest when the alternative was fully available.","th":[0],"p":2,"q":[12,92]},{"id":"yusuf_cause_me_to_die_muslim","t":"The Wish at the Top","b":"Reunited, restored, entrusted with Egypt, his prayer was to be taken as one who submits and joined with the righteous. He did not ask to keep a single part of it.","th":[0],"p":2,"q":[12,101]},{"id":"nuh_istighfar_rain","t":"Ask, and the Sky Opens","b":"Nuh told his people to seek their Lord's forgiveness, then listed what would follow: rain in abundance, wealth, children, gardens, rivers. Istighfar was offered as the practical answer, not the pious one.","th":[0],"p":3,"q":[71,10]},{"id":"nuh_board_in_the_name","t":"Its Course and Its Anchorage","b":"He told them to board in the name of Allah, and named both the sailing and the mooring in the same breath. Beginning something in His name is not a formality. It is a statement about who is steering.","th":[0],"p":3,"q":[11,41]},{"id":"nuh_overpowered_help_me","t":"Centuries, Then Four Words","b":"After a lifetime of being mocked, his prayer was very short: I am overcome, so help. You are allowed to run out of words. Say the short one.","th":[0],"p":3,"q":[54,10]},{"id":"nuh_the_son","t":"The One He Could Not Save","b":"He called his own son aboard, and his son chose a mountain instead. There is no protector that day except for the one Allah has mercy upon. Guidance is not an inheritance a father can hand down.","th":[0],"p":3,"q":[11,43]},{"id":"nuh_a_thousand_years","t":"Fifty Short of a Thousand","b":"He stayed among a people who would not listen for nine and a half centuries. Whatever you have been enduring, you are not yet at the limit of what a servant of Allah has been asked to carry.","th":[0],"p":3,"q":[29,14]},{"id":"adam_taught_the_names","t":"The First Gift Was Knowledge","b":"Before the angels were told to prostrate, Adam was taught the names of all things. Human honour opened with being taught. What you learn deliberately this week is not a side project.","th":[0],"p":4,"q":[2,31]},{"id":"adam_we_wronged_ourselves","t":"The Words That Started Everything Again","b":"Adam and his wife did not explain, minimise or blame. They said they had wronged themselves, and that without forgiveness and mercy they were lost. That is the shape of a repentance that works.","th":[0],"p":4,"q":[7,23]},{"id":"adam_received_words","t":"He Was Given the Apology","b":"Adam received words from his Lord, and his Lord turned to him. Even the language of returning was itself a gift. If you do not know how to come back, ask to be shown how.","th":[0],"p":4,"q":[2,37]},{"id":"adam_he_forgot","t":"Forgetting Is in the Design","b":"The Quran says a covenant was taken from Adam, and he forgot, and no firm resolve was found in him. Your forgetfulness is neither new nor disqualifying. Build the reminders instead of the guilt.","th":[0],"p":4,"q":[20,115]},{"id":"adam_children_honoured","t":"Carried Over Land and Sea","b":"Allah says He honoured the children of Adam, carried them on land and sea, provided them good things and favoured them. Whatever anyone has told you about your worth, there is an older statement on the record.","th":[0],"p":4,"q":[17,70]},{"id":"yunus_in_the_darkness","t":"The Prayer From Inside the Dark","b":"Layers of darkness, and no bargaining at all. He declared that there is no god but Him, exalted Him, and named himself among the wrongdoers. He asked for nothing, and that was the prayer that was answered.","th":[0],"p":5,"q":[21,87]},{"id":"yunus_we_save_the_believers","t":"And Thus We Save","b":"Allah answered him and delivered him from the distress, and then added that this is how He saves the believers. The rescue was reported as a rule, not as an exception.","th":[0],"p":5,"q":[21,88]},{"id":"yunus_had_he_not_glorified","t":"What He Had Already Banked","b":"The Quran says that had he not been of those who glorify Allah, he would have remained in that belly until the Day they are raised. The dhikr you keep in easy times is what surfaces in the dark.","th":[0],"p":5,"q":[37,143]},{"id":"yunus_do_not_be_like_him","t":"Wait, and Do Not Cry Out","b":"The Prophet was told to be patient for the decision of his Lord, and not to be like the companion of the fish who called out while choked with grief. Even prophets are told: not yet.","th":[0],"p":5,"q":[68,48]},{"id":"ayyub_harm_has_touched_me","t":"He Never Asked for It Back","b":"Years of illness, and the whole supplication was two statements: harm has touched me, and You are the Most Merciful of the merciful. He described his condition, then described his Lord, and dictated no outcome.","th":[0],"p":6,"q":[21,83]},{"id":"ayyub_we_responded","t":"And His Family Came Back","b":"Allah answered him, removed what afflicted him, and gave him his family and the like of them with them, as a mercy and a reminder to those who worship. Restoration was never off the table.","th":[0],"p":6,"q":[21,84]},{"id":"ayyub_satan_touched_me","t":"He Called Out to the Right Address","b":"He named what was happening to him honestly, and said it to Allah rather than about Him. Complaint aimed upward is worship. Complaint aimed sideways is only noise.","th":[0],"p":6,"q":[38,41]},{"id":"ayyub_excellent_servant","t":"How He Is Described","b":"The verdict of the Quran on Ayyub is short: We found him patient, an excellent servant, one who repeatedly turned back. That is what all those years of illness were being written down as.","th":[0],"p":6,"q":[38,44]},{"id":"maryam_wish_i_had_died","t":"She Said It Out Loud","b":"Alone at the palm tree, she wished she had died before this and been a thing forgotten. The Quran preserved that sentence instead of editing it out. Anguish spoken to Allah is not disbelief.","th":[0],"p":7,"q":[19,23]},{"id":"maryam_shake_the_trunk","t":"Shake the Trunk","b":"A woman in labour was told to shake a date palm toward herself. She could not have moved it, and the dates were coming regardless. Do your part anyway. The part is the point.","th":[0],"p":7,"q":[19,25]},{"id":"maryam_provision_in_the_chamber","t":"Where Is This From?","b":"Zakariyya kept finding provision with her and asked where it came from. She said it was from Allah, who provides without measure. She never once seemed surprised by it.","th":[0],"p":7,"q":[3,37]},{"id":"isa_servant_of_allah","t":"The First Thing He Said","b":"A newborn spoke, and the first claim he made was that he was a servant of Allah, given the Scripture and made a prophet. Everything later said about him was answered in his own opening sentence.","th":[0],"p":8,"q":[19,30]},{"id":"isa_prayer_and_zakah","t":"As Long As I Remain Alive","b":"He said he had been enjoined with prayer and purifying charity for as long as he lived. No retirement clause, no exempt season. The obligation was described as lasting exactly as long as the life does.","th":[0],"p":8,"q":[19,31]},{"id":"maryam_devoutly_obedient","t":"How She Is Introduced","b":"The Quran presents Maryam as an example for the believers and describes her by her chastity, her belief and her devotion, not by what was done to her or said about her. You are not your circumstances either.","th":[0],"p":7,"q":[66,12]},{"id":"dawud_mountains_repeat","t":"The Mountains Joined In","b":"Allah gave Dawud favour and told the mountains and the birds to echo his praise along with him. When a heart praises sincerely, it turns out it was never doing it alone.","th":[0],"p":9,"q":[34,10]},{"id":"dawud_fell_bowing","t":"He Understood Immediately","b":"The moment Dawud realised he had been tested, he sought forgiveness, fell down bowing and turned back. There was no gap between recognition and return. The gap is where sins settle in.","th":[0],"p":9,"q":[38,24]},{"id":"sulayman_enable_me_to_be_grateful","t":"He Smiled, Then He Prayed","b":"He overheard an ant warning her colony about his army, and it made him smile, and then made him ask Allah to enable him to be grateful for the favour. A small thing became worship in a single step.","th":[0],"p":10,"q":[27,19]},{"id":"sulayman_test_of_gratitude","t":"A Throne Arrives, and He Suspects Himself","b":"With a kingdom nobody has matched, his reading of the moment was that this is from the favour of his Lord, to test whether he would be grateful or ungrateful. He treated the blessing as the exam paper.","th":[0],"p":10,"q":[27,40]},{"id":"sulayman_kingdom_after_forgiveness","t":"Forgive Me First","b":"His famous request for an unmatched kingdom opens with the half nobody quotes: my Lord, forgive me. He asked for pardon before he asked for anything else at all.","th":[0],"p":10,"q":[38,35]},{"id":"yaqub_do_not_despair","t":"Go and Look Again","b":"A blind old man who had lost two sons sent his remaining children out to search, and told them that no one despairs of the comfort of Allah except a disbelieving people. Hope was framed as a matter of creed.","th":[0],"p":11,"q":[12,87]},{"id":"shuayb_my_success_is_from_allah","t":"I Only Want to Set It Right","b":"Shuayb told his people he wanted nothing but reform as far as he was able, and that his ability to do so came only through Allah. Intention stated, capacity acknowledged, outcome handed over.","th":[0],"p":12,"q":[11,88]},{"id":"zakariyya_do_not_leave_me_alone","t":"Do Not Leave Me Alone","b":"He asked not to be left without an heir, and then said the truer thing anyway: and You are the best of inheritors. He wanted the child. He also knew who would remain if he never received one.","th":[0],"p":13,"q":[21,89]},{"id":"yahya_take_it_with_strength","t":"Hold It Firmly","b":"Yahya was told as a child to take the Scripture with strength, and was given sound judgement while still young. Revelation was not handed to him to keep on a shelf.","th":[0],"p":14,"q":[19,12]},{"id":"hud_every_creature_by_the_forelock","t":"Outnumbered and Unbothered","b":"Facing a hostile people alone, Hud said he relied upon Allah, and that there is no creature He does not hold by its forelock. Nothing in that room was outside His grip, including the room.","th":[0],"p":15,"q":[11,56]},{"id":"ismail_true_to_his_promise","t":"He Kept His Word","b":"The Quran singles out one quality in Ismail above the rest: he was true to his promise. Of everything that could have been recorded about him, that is what was.","th":[0],"p":16,"q":[19,54]},{"id":"zakariyya_never_disappointed_in_asking","t":"Never Disappointed in Asking","b":"Old, his bones weakened and his head white with age, Zakariyya called to his Lord in private and said he had never been disappointed in calling upon Him. He asked from a long history of being answered.","th":[0,4],"p":13,"q":[19,4]},{"id":"yaqub_grief_taken_to_the_right_place","t":"Grief Taken to the Right Place","b":"Yaqub said he complained of his grief and sorrow only to Allah, and that he knew from Allah what they did not know. The grief was not hidden or denied. It was carried to the One who could answer it.","th":[0,2],"p":11,"q":[12,86]},{"id":"dawud_work_in_gratitude","t":"Work, in Gratitude","b":"After describing what was made for Sulayman, Allah says: work, family of Dawud, in gratitude, and few of My servants are grateful. Gratitude is described as something you do, not only something you say.","th":[0,7],"p":9,"q":[34,13]},{"id":"mercy_do_not_despair","t":"Addressed to the Ones Who Went Furthest","b":"The verse opens by calling them servants who transgressed against themselves, and then tells them not to despair. The people most convinced they are beyond it are the ones being spoken to by name.","th":[1],"p":null,"q":[39,53]},{"id":"mercy_encompasses_all","t":"Wider Than Everything Else","b":"Allah says His punishment reaches whom He wills, and then, in the same breath, that His mercy encompasses all things. One of those two is described as unbounded, and it is not the first.","th":[1],"p":null,"q":[7,156]},{"id":"mercy_decreed_upon_himself","t":"He Wrote It Upon Himself","b":"Nobody obliged Him. The Quran says He decreed mercy upon Himself, and then explains what that means for whoever does wrong in ignorance and afterwards repents and reforms.","th":[1],"p":null,"q":[6,54]},{"id":"mercy_wrong_then_seeks","t":"The Door Was Never Locked","b":"Whoever does a wrong or wrongs himself and then seeks the forgiveness of Allah will find Allah Forgiving and Merciful. The sequence has two steps, and the second one is the only work you have.","th":[1],"p":null,"q":[4,110]},{"id":"mercy_who_forgives_but_allah","t":"A Question With One Answer","b":"Those who remember Allah after a wrong and ask forgiveness are asked a question in the middle of the verse: and who forgives sins except Allah? It is not rhetorical comfort. It is a redirect.","th":[1],"p":null,"q":[3,135]},{"id":"mercy_sincere_repentance","t":"Sincere, Not Perfect","b":"Believers are told to turn to Allah in a repentance that is sincere. The condition placed on it is honesty, not a guarantee that you will never return to it.","th":[1],"p":null,"q":[66,8]},{"id":"mercy_evil_replaced_with_good","t":"Not Erased. Exchanged.","b":"For those who repent, believe and act righteously, the Quran says Allah will replace their evil deeds with good ones. The record is not merely wiped. It is rewritten in your favour.","th":[1],"p":null,"q":[25,70]},{"id":"mercy_accepts_repentance","t":"He Is the One Who Accepts","b":"It is He who accepts repentance from His servants and pardons misdeeds, and He knows what you do. The knowledge and the pardon are stated together. Nothing has to be hidden for it to work.","th":[1],"p":null,"q":[42,25]},{"id":"mercy_perpetual_forgiver","t":"Four Conditions, One Promise","b":"Repents, believes, does righteousness, then stays guided. The promise attached is that He is the Perpetual Forgiver. Notice that continuing is on the list, and that forgiveness is not rationed to it.","th":[1],"p":null,"q":[20,82]},{"id":"mercy_loves_the_repentant","t":"He Loves Them for It","b":"Allah loves those who are constantly repentant and those who purify themselves. Coming back is not tolerated. It is the thing being loved.","th":[1],"p":null,"q":[2,222]},{"id":"mercy_forgiver_of_sin","t":"Read the Order of the Names","b":"Forgiver of sin, Acceptor of repentance, Severe in punishment, Owner of abundance. Three of those four are turned toward you. Learn the order in which He introduces Himself.","th":[1],"p":null,"q":[40,3]},{"id":"mercy_call_upon_me","t":"Call, and Be Answered","b":"Your Lord says to call upon Him and He will respond. The verse then names arrogance, not sin, as what keeps people from asking. Refusing to ask is treated as the serious thing.","th":[1],"p":null,"q":[40,60]},{"id":"mercy_i_am_near","t":"No Intermediary in the Sentence","b":"When My servants ask you about Me, He does not say tell them. He says I am near. The messenger is skipped over in the grammar itself.","th":[1],"p":null,"q":[2,186]},{"id":"mercy_inform_my_servants","t":"Announce It","b":"Allah instructs His Messenger to inform His servants that He is the Forgiving, the Merciful. This was something to be told to people, not left for them to work out on their own.","th":[1],"p":null,"q":[15,49]},{"id":"mercy_do_they_not_know","t":"Do They Not Know?","b":"The verse asks whether they do not know that Allah is the One who accepts repentance from His servants and takes the charities. It reads as surprise that anyone would still doubt it.","th":[1],"p":null,"q":[9,104]},{"id":"mercy_repent_soon_after","t":"Soon, Not Someday","b":"Repentance accepted by Allah is described as belonging to those who do wrong in ignorance and then repent soon afterwards. The urgency is in the verse, not in the guilt.","th":[1],"p":null,"q":[4,17]},{"id":"mercy_merciful_and_loving","t":"Merciful, and Loving","b":"Shuayb told his people to seek forgiveness and turn back, and closed with two names together: Merciful, and Loving. Being forgiven and being wanted are not the same thing, and both are on offer.","th":[1],"p":null,"q":[11,90]},{"id":"mercy_forgiving_affectionate","t":"After the Trench","b":"A surah that recounts believers burned alive for their faith names Him the Forgiving, the Affectionate. That placement is deliberate. Read what surrounds it.","th":[1],"p":null,"q":[85,14]},{"id":"mercy_do_you_not_like","t":"A Question Aimed at the Grudge","b":"Told to keep giving to someone who had wronged them badly, the believers were asked whether they would not like Allah to forgive them. The reasoning stops the argument dead.","th":[1],"p":null,"q":[24,22]},{"id":"mercy_satan_threatens_poverty","t":"Two Voices, Told Apart","b":"One promises poverty and orders immorality. The other promises forgiveness and abundance. The verse names which is which so you can identify the voice by what it offers.","th":[1],"p":null,"q":[2,268]},{"id":"mercy_repents_and_reforms","t":"Repent and Repair","b":"After a serious ruling, the verse turns: whoever repents after his wrongdoing and reforms, Allah will turn to him. Reform is named as part of the return, and the return is still open.","th":[1],"p":null,"q":[5,39]},{"id":"mercy_not_punished_while_seeking","t":"A Shield Made of Asking","b":"Allah says He would not punish them while they were seeking forgiveness. Istighfar is described here as protection in the present, not only as repair of the past.","th":[1],"p":null,"q":[8,33]},{"id":"mercy_forgiveness_despite_wrongdoing","t":"Despite, Not Because","b":"Your Lord is full of forgiveness toward people despite their wrongdoing. The word doing the work in that sentence is despite. He is not waiting for you to deserve it first.","th":[1],"p":null,"q":[13,6]},{"id":"mercy_vast_in_forgiveness","t":"He Knew You Before You Did","b":"The verse says He is vast in forgiveness, and then that He knew you when He produced you from the earth and when you were fetuses. Nothing you have done has updated His information.","th":[1],"p":null,"q":[53,32]},{"id":"mercy_often_returning","t":"For the Ones Who Keep Coming Back","b":"Your Lord knows best what is in your souls. If you are righteous, then He is Forgiving to those who often return. The word is repetition, and it is used approvingly.","th":[1],"p":null,"q":[17,25]},{"id":"mercy_ever_merciful_to_believers","t":"He and His Angels","b":"He is the One who sends blessings upon you, and His angels, to bring you out of darkness into light. And He is ever Merciful to the believers. Something is being done for you while you read this.","th":[1],"p":null,"q":[33,43]},{"id":"mercy_pardon_and_ask_for_them","t":"After They Cost Him Everything","b":"Following a battle lost through disobedience, the Prophet was told to pardon them, seek forgiveness for them, and consult them in the matter. All three, in that order, to the same people.","th":[1],"p":null,"q":[3,159]},{"id":"mercy_pardon_and_overlook","t":"Three Verbs Before the Name","b":"Pardon, overlook, forgive, and then Allah is Forgiving and Merciful. The names arrive as the reason, placed at the end of the sentence like a signature.","th":[1],"p":null,"q":[64,14]},{"id":"mercy_he_pardons_much","t":"And He Pardons Much","b":"Whatever strikes you of disaster is from what your hands have earned, and He pardons much. Half of that sentence gets quoted at people. The other half is the mercy in it.","th":[1],"p":null,"q":[42,30]},{"id":"mercy_would_leave_no_creature","t":"Nobody Would Be Left","b":"If Allah were to hold people to account for what they have earned, He would not leave a single living creature on the surface of the earth. You are reading this because He does not.","th":[1],"p":null,"q":[35,45]},{"id":"mercy_will_they_not_repent","t":"Still Asking","b":"After describing serious error, the verse asks: will they not repent to Allah and seek His forgiveness? The invitation is extended to exactly the people who had just been corrected.","th":[1],"p":null,"q":[5,74]},{"id":"mercy_except_those_who_repent","t":"The Exception Clause","b":"A severe verse about concealing guidance carries an exception: except for those who repent, put things right, and make clear. Almost every warning in the Quran has a door built into it.","th":[1],"p":null,"q":[2,160]},{"id":"mercy_hasten_to_forgiveness","t":"Race Toward the Forgiveness","b":"The command is to hurry toward forgiveness from your Lord and a garden as wide as the heavens and the earth. Forgiveness is described as something to run toward, not to wait for.","th":[1],"p":null,"q":[3,133]},{"id":"mercy_race_toward","t":"Compete for This","b":"Race one another for forgiveness from your Lord. Of everything a person could compete over, this is the one the Quran actually encourages. What are you currently racing for?","th":[1],"p":null,"q":[57,21]},{"id":"mercy_return_before","t":"Before, Not After","b":"Return to your Lord and submit to Him before the punishment comes upon you and you are not helped. The word before is the whole verse. Nothing is being withheld except time.","th":[1],"p":null,"q":[39,54]},{"id":"mercy_had_they_come_to_you","t":"They Only Had to Come","b":"The verse says that if, when they had wronged themselves, they had come and sought forgiveness of Allah, they would have found Him Accepting and Merciful. The obstacle was the coming, not the receiving.","th":[1],"p":null,"q":[4,64]},{"id":"mercy_ever_accepting","t":"The Last Instruction","b":"Near the end of the Prophet's life, with victory arriving, the instruction was to glorify with praise and seek forgiveness, because He is ever Accepting of repentance. Even success ends in istighfar.","th":[1],"p":null,"q":[110,3]},{"id":"mercy_ask_forgiveness_for_your_sin","t":"Even the Best of Us","b":"The command to seek forgiveness for one's sin was given to the Messenger himself, alongside the command to know that there is no god but Allah. Nobody in this religion is above asking.","th":[1],"p":null,"q":[47,19]},{"id":"mercy_avoid_the_major","t":"One Threshold to Hold","b":"Avoid the major sins you have been forbidden, and Allah will remove your lesser ones and admit you to a noble entrance. The strategy is stated plainly: hold the line where it matters most.","th":[1],"p":null,"q":[4,31]},{"id":"mercy_accept_the_best","t":"Judged by Your Best Day","b":"Of those people, Allah says He accepts the best of what they did and overlooks their misdeeds. Your record is not being read at its lowest point.","th":[1],"p":null,"q":[46,16]},{"id":"mercy_remove_their_misdeeds","t":"Written Off Entirely","b":"Those who believe and do righteous deeds are promised the removal of their misdeeds and reward according to the best of what they used to do. Both halves of that verse are generous.","th":[1],"p":null,"q":[29,7]},{"id":"mercy_allah_will_love_you","t":"The Test of the Claim","b":"If you love Allah, then follow the Messenger, and Allah will love you and forgive your sins. Love is measured here by following, and repaid with both love and forgiveness.","th":[1],"p":null,"q":[3,31]},{"id":"mercy_none_would_be_pure","t":"Nobody Purified Themselves","b":"Were it not for the favour of Allah upon you and His mercy, not one of you would ever have been pure. Whatever discipline you think you built, the verse assigns credit elsewhere.","th":[1],"p":null,"q":[24,21]},{"id":"mercy_the_three_left_behind","t":"Until the Earth Closed In","b":"Three men were shunned until the earth felt narrow to them and their own souls felt narrow, and they knew there was no refuge from Allah except in Him. Then He turned to them so they could repent.","th":[1],"p":null,"q":[9,118]},{"id":"mercy_angels_ask_for_you","t":"Someone Is Praying for You","b":"Those who carry the Throne ask forgiveness for the believers, saying that His mercy and knowledge encompass all things, and asking Him to forgive those who repented. There are angels making dua for you by description.","th":[1],"p":null,"q":[40,7]},{"id":"mercy_affection_appointed","t":"Love, Placed There by Him","b":"For those who believe and do righteous deeds, the Most Merciful will appoint affection. Even the love people have for you is described as something He assigns.","th":[1],"p":null,"q":[19,96]},{"id":"mercy_would_have_hastened","t":"The Delay Is the Mercy","b":"Your Lord is the Forgiving, full of mercy. Were He to hold them accountable for what they earned, He would have hastened the punishment. Time you still have is the verse in action.","th":[1],"p":null,"q":[18,58]},{"id":"mercy_hundred_parts","t":"Ninety-Nine Still Held Back","b":"The Prophet said Allah made mercy in a hundred parts, sent down one part among all creation, and kept ninety-nine with Him. Every kindness you have ever received came out of the one part.","th":[1],"p":null,"h":{"c":"Sahih Muslim","n":"2752","u":"https://sunnah.com/muslim:2752","g":"Sahih","by":null}},{"id":"mercy_prevails_over_wrath","t":"Written Before Anything Else","b":"The Prophet reported that when Allah completed the creation, He wrote in a Book kept with Him that His mercy prevails over His wrath. That was recorded before any of us had done anything either way.","th":[1],"p":null,"h":{"c":"Sahih al-Bukhari","n":"3194","u":"https://sunnah.com/bukhari:3194","g":"Sahih","by":null}},{"id":"mercy_mother_and_child","t":"More Merciful Than She Is","b":"Seeing a woman searching frantically for her child and then clutching him, the Prophet asked his companions whether she would throw him into a fire. They said no. He said Allah is more merciful to His servants than she is to her child.","th":[1],"p":null,"h":{"c":"Sahih al-Bukhari","n":"5999","u":"https://sunnah.com/bukhari:5999","g":"Sahih","by":null}},{"id":"mercy_lost_camel_joy","t":"Happier Than the Man Who Found It","b":"The Prophet described a man who loses his camel in the desert with all his food and water on it, gives up, lies down to die, and then finds it standing beside him. Allah, he said, is more delighted at your repentance than that.","th":[1],"p":null,"h":{"c":"Sahih al-Bukhari","n":"6308","u":"https://sunnah.com/bukhari:6308","g":"Sahih","by":null}},{"id":"mercy_a_people_who_sin","t":"You Were Made to Need This","b":"The Prophet said that if you did not sin, Allah would take you away and bring a people who sin and seek forgiveness so that He may forgive them. Your need for forgiveness is not a defect in the design.","th":[1],"p":null,"h":{"c":"Sahih Muslim","n":"2749","u":"https://sunnah.com/muslim:2749","g":"Sahih","by":null}},{"id":"mercy_hand_by_night_and_day","t":"Two Shifts, Always Open","b":"The Prophet said Allah extends His hand by night so the one who sinned by day may repent, and by day so the one who sinned by night may repent, until the sun rises from the west. There is no closing time before that.","th":[1],"p":null,"h":{"c":"Sahih Muslim","n":"2759","u":"https://sunnah.com/muslim:2759","g":"Sahih","by":null}},{"id":"mercy_as_my_servant_thinks","t":"Think Better of Him","b":"In a hadith qudsi the Prophet reported that Allah says He is as His servant expects Him to be. What you assume about how He will receive you is not a private feeling. It shapes what you get.","th":[1],"p":null,"h":{"c":"Sahih Muslim","n":"2675","u":"https://sunnah.com/muslim:2675","g":"Sahih","by":null}},{"id":"mercy_forbidden_oppression","t":"He Forbade It to Himself","b":"In a long hadith qudsi, Allah declares that He has forbidden injustice for Himself and made it forbidden among His servants, and then invites them to seek His guidance, His food and His forgiveness. Nothing unjust has ever happened to you from Him.","th":[1],"p":null,"h":{"c":"Sahih Muslim","n":"2577","u":"https://sunnah.com/muslim:2577","g":"Sahih","by":null}},{"id":"mercy_seventy_times_a_day","t":"The Sinless One Asked Most","b":"The Prophet said that he sought the forgiveness of Allah and turned to Him more than seventy times in a day. Istighfar was never a measure of how much wrong he had done.","th":[1],"p":null,"h":{"c":"Sahih al-Bukhari","n":"6307","u":"https://sunnah.com/bukhari:6307","g":"Sahih","by":null}},{"id":"mercy_hundred_times_a_day","t":"A Hundred, Every Day","b":"The Prophet told people to repent to Allah, saying that he himself repented to Him a hundred times a day. The instruction came attached to his own practice, not above it.","th":[1],"p":null,"h":{"c":"Sahih Muslim","n":"2702","u":"https://sunnah.com/muslim:2702","g":"Sahih","by":null}},{"id":"mercy_as_long_as_you_call","t":"As Long As You Keep Calling","b":"A hadith qudsi reported by the Prophet: as long as the servant calls upon Him and hopes in Him, Allah forgives whatever he has done and does not mind; were his sins to reach the clouds and then he asked forgiveness, He would forgive him.","th":[1],"p":null,"h":{"c":"Jamiʽ at-Tirmidhi","n":"3540","u":"https://sunnah.com/tirmidhi:3540","g":"Hasan","by":"Darussalam"}},{"id":"mercy_intention_recorded","t":"The Deed You Meant to Do","b":"The Prophet reported that when a servant intends a good deed it is written for him even before he does it, and when he intends a bad deed and leaves it for the sake of Allah, that too is written in his favour.","th":[1],"p":null,"h":{"c":"Sahih al-Bukhari","n":"7501","u":"https://sunnah.com/bukhari:7501","g":"Sahih","by":null}},{"id":"mercy_water_in_a_shoe","t":"Water in a Shoe","b":"The Prophet told of a thirsty man who drank from a well and then saw a dog eating mud from thirst. He went down again, filled his shoe with water and gave it to drink, and Allah thanked him and forgave him. There is reward, he said, in every living creature.","th":[1,5],"p":null,"h":{"c":"Sahih al-Bukhari","n":"6009","u":"https://sunnah.com/bukhari:6009","g":"Sahih","by":null}},{"id":"mercy_if_either_truly_knew","t":"If Either Truly Knew","b":"The Prophet said that if the believer knew the punishment with Allah, no one would feel sure of His Paradise, and if the disbeliever knew the mercy with Allah, no one would despair of His Paradise. Hope and fear are both meant to stay awake.","th":[1,6],"p":null,"h":{"c":"Sahih Muslim","n":"2755","u":"https://sunnah.com/muslim:2755","g":"Sahih","by":null}},{"id":"mercy_near_to_those_who_do_good","t":"Mercy Is Near","b":"The verse tells us to call upon Allah in fear and in hope, and then says that His mercy is near to those who do good. Not distant, and not held back for later. Near.","th":[1,4],"p":null,"q":[7,56]},{"id":"mercy_look_at_the_traces","t":"Look at the Traces","b":"The verse asks you to look at the traces of Allah’s mercy, how He gives the earth life after it was lifeless, and says that the One who does this will give life to the dead. What looked finished was waiting.","th":[1,2],"p":null,"q":[30,50]},{"id":"mercy_your_hardship_weighed_on_him","t":"Your Hardship Weighed on Him","b":"The verse describes the Messenger as one of your own: your hardship is grievous to him, he is deeply concerned for you, and to the believers he is kind and merciful. This is how revelation describes the one who brought it.","th":[1],"p":null,"q":[9,128]},{"id":"patience_with_hardship_ease","t":"With It, Not After It","b":"The verse does not say that ease follows hardship. It says that with hardship there is ease, and then repeats the sentence. The relief is not queued behind the difficulty. It is inside it.","th":[2],"p":null,"q":[94,5]},{"id":"patience_a_way_out","t":"An Exit You Cannot See Yet","b":"Whoever is mindful of Allah, He makes for him a way out. The verse does not describe the exit or say when it appears. It only names the condition attached to it.","th":[2],"p":null,"q":[65,2]},{"id":"patience_he_is_sufficient","t":"Sufficient Is a Strong Word","b":"Whoever relies upon Allah, He is sufficient for him. Not helpful, not supportive. Sufficient. Nothing else in the arrangement needs topping up.","th":[2],"p":null,"q":[65,3]},{"id":"patience_hasbunallah","t":"What They Said When Told to Be Afraid","b":"People came to frighten them with the size of the army gathering against them, and it increased their faith instead. What they said was that Allah is enough for them and the best disposer of affairs.","th":[2],"p":null,"q":[3,173]},{"id":"patience_allah_is_with_the_patient","t":"Company, Not Just Reward","b":"Seek help through patience and prayer, and Allah is with the patient. The payment for sabr named here is His presence, offered while the difficulty is still going on.","th":[2],"p":null,"q":[2,153]},{"id":"patience_we_will_test_you","t":"Named in Advance","b":"Fear, hunger, loss of wealth, lives and fruits. The list was published beforehand, followed by glad tidings for those who are patient. None of it arrives unannounced.","th":[2],"p":null,"q":[2,155]},{"id":"patience_inna_lillah","t":"Two Clauses, One Sentence","b":"We belong to Allah, and to Him we are returning. The words people say at a graveside are a statement of ownership first. Grief is easier to hold when you know whose it was.","th":[2],"p":null,"q":[2,156]},{"id":"patience_within_its_capacity","t":"Sized to You","b":"Allah does not burden a soul beyond its capacity. That is not a promise that it will feel manageable. It is a statement about who did the measuring.","th":[2],"p":null,"q":[2,286]},{"id":"patience_reward_without_account","t":"The Only Uncounted Payment","b":"The patient will be given their reward without measure. Every other deed in the Quran has a stated multiplier. This one is left deliberately open.","th":[2],"p":null,"q":[39,10]},{"id":"patience_and_allah_is_with","t":"Obey, Do Not Quarrel, Endure","b":"Before a battle, the instruction was to obey, avoid disputing so their strength would not leave them, and be patient. Internal argument was named as the thing that drains you, not the enemy.","th":[2],"p":null,"q":[8,46]},{"id":"patience_persevere_and_endure","t":"Outlast Them","b":"Be patient, outdo others in patience, remain stationed, and be mindful of Allah. Four commands, and three of them are about staying where you were put.","th":[2],"p":null,"q":[3,200]},{"id":"patience_only_through_allah","t":"Even Patience Is Given","b":"Be patient, and your patience is only through Allah. If you have been holding on, that capacity was supplied. Ask for more of it the way you would ask for anything else.","th":[2],"p":null,"q":[16,127]},{"id":"patience_be_and_it_is","t":"One Word","b":"His command, when He intends a thing, is only that He says to it: be. And it is. Whatever you have been asking for is one word away on His side of the arrangement.","th":[2],"p":null,"q":[36,82]},{"id":"patience_written_before","t":"Already in the Register","b":"No disaster strikes on the earth or in yourselves except that it is in a record before He brings it into being. Your worst day had a file open before the world did.","th":[2],"p":null,"q":[57,22]},{"id":"patience_he_guides_the_heart","t":"What Is Guided Is the Heart","b":"No calamity strikes except by permission of Allah, and whoever believes in Him, He guides his heart. The promise attached to the calamity is not removal. It is a guided heart while it lasts.","th":[2],"p":null,"q":[64,11]},{"id":"patience_do_not_weaken","t":"Spoken After a Defeat","b":"Do not weaken and do not grieve; you will be superior if you are believers. This was said to people who had just lost, not to people who had just won.","th":[2],"p":null,"q":[3,139]},{"id":"patience_when_is_the_help","t":"Even the Messenger Asked","b":"The verse describes hardship so severe that the messenger and those with him said: when will the help of Allah come? The Quran records the question, then answers that His help is near.","th":[2],"p":null,"q":[2,214]},{"id":"patience_until_it_is_evident","t":"The Test Reveals, It Does Not Inform","b":"We will test you until We make evident those who strive and those who are patient. He already knows. The test is what makes it visible, including to you.","th":[2],"p":null,"q":[47,31]},{"id":"patience_do_people_think","t":"Saying It Is Not Enough","b":"Do people think they will be left to say we believe and not be tested? The claim is accepted; the verse simply announces that it will be examined.","th":[2],"p":null,"q":[29,2]},{"id":"patience_those_who_strive","t":"Move, and Be Shown","b":"Those who strive for Us, We will surely guide them to Our ways. The guidance is promised to the ones already walking. Direction comes after motion, not before it.","th":[2],"p":null,"q":[29,69]},{"id":"patience_reward_not_lost","t":"Nothing Goes Unrecorded","b":"Be patient, for Allah does not let the reward of those who do good be lost. Everything you did that nobody noticed is filed somewhere that does not lose things.","th":[2],"p":null,"q":[11,115]},{"id":"patience_peace_for_what_you_endured","t":"The Greeting at the Door","b":"The angels greet them with peace for what they patiently endured. The first words spoken to them refer back to the hardest part of their lives.","th":[2],"p":null,"q":[13,24]},{"id":"patience_the_chamber","t":"A Room Bought With Endurance","b":"Those will be awarded the highest chamber for what they patiently endured, and met there with greeting and peace. The endurance was the price, and it has already been paid.","th":[2],"p":null,"q":[25,75]},{"id":"patience_garden_and_silk","t":"Repaid in Garden and Silk","b":"He rewarded them for what they patiently endured with a garden and silk. The verse names the specific comfort given in exchange for the specific discomfort borne.","th":[2],"p":null,"q":[76,12]},{"id":"patience_advised_each_other","t":"Four Things, and the Last One Is for Others","b":"By time, mankind is in loss, except those who believe, do righteous deeds, counsel one another to truth, and counsel one another to patience. The final item is patience you are supposed to give other people.","th":[2],"p":null,"q":[103,3]},{"id":"patience_rely_upon_allah","t":"Rely, and Let That Be Enough","b":"Rely upon Allah, and sufficient is Allah as a disposer of affairs. The command and its justification are placed in the same short verse so that neither can be taken alone.","th":[2],"p":null,"q":[33,3]},{"id":"patience_worship_and_rely","t":"Worship Him and Lean on Him","b":"To Allah belongs the unseen of the heavens and the earth, and to Him the whole matter is returned, so worship Him and rely upon Him. Reliance is presented as the natural consequence of knowing who holds the unseen.","th":[2],"p":null,"q":[11,123]},{"id":"patience_why_should_we_not","t":"Why Would We Not?","b":"The messengers answered persecution with a question: why should we not rely upon Allah when He has guided us to our ways? Past guidance was treated as evidence for present trust.","th":[2],"p":null,"q":[14,12]},{"id":"patience_if_allah_aids_you","t":"The Only Arithmetic That Matters","b":"If Allah aids you, none can overcome you; and if He forsakes you, who is there after Him to help? Then it says: so let the believers rely upon Allah. The conclusion is drawn for you.","th":[2],"p":null,"q":[3,160]},{"id":"patience_do_not_grieve","t":"Two Men in a Cave","b":"Hunted, hidden, with searchers standing at the entrance, he told his companion not to grieve because Allah is with us. Then tranquillity was sent down. The reassurance came before the rescue.","th":[2],"p":null,"q":[9,40]},{"id":"patience_is_not_allah_sufficient","t":"A Question Left Open","b":"Is Allah not sufficient for His servant? The Quran asks it and moves on without arguing. Some questions are answered by how uncomfortable they are to answer honestly.","th":[2],"p":null,"q":[39,36]},{"id":"patience_no_remover_except_him","t":"One Address for Both","b":"If Allah touches you with harm, none can remove it except Him; and if He touches you with good, He is capable of all things. The same hand is named in both halves of the verse.","th":[2],"p":null,"q":[6,17]},{"id":"patience_do_not_fear_do_not_grieve","t":"Said Twice, in Both Directions","b":"To those who say our Lord is Allah and then stay upright, the angels descend saying do not fear and do not grieve. One phrase faces the future and the other faces the past. Both are covered.","th":[2],"p":null,"q":[41,30]},{"id":"patience_perhaps_you_hate","t":"You May Be Reading It Backwards","b":"Perhaps you hate a thing and it is good for you, and perhaps you love a thing and it is bad for you. Allah knows and you do not. Nothing in that verse asks you to enjoy it.","th":[2],"p":null,"q":[2,216]},{"id":"patience_he_has_not_forsaken_you","t":"The Silence Was Not Abandonment","b":"When revelation paused and people said he had been left, the answer came: your Lord has not taken leave of you, nor has He detested you. A quiet season is not a verdict.","th":[2],"p":null,"q":[93,3]},{"id":"patience_wondrous_affair","t":"Both Ways Are Profitable","b":"The Prophet said the affair of the believer is wondrous, because all of it is good, and that is for no one but the believer: if ease comes he is grateful and it is good for him, and if hardship comes he is patient and it is good for him.","th":[2],"p":null,"h":{"c":"Sahih Muslim","n":"2999","u":"https://sunnah.com/muslim:2999","g":"Sahih","by":null}},{"id":"patience_even_a_thorn","t":"Down to the Thorn","b":"The Prophet said no fatigue, illness, anxiety, sorrow, hurt or distress touches a Muslim, even the prick of a thorn, without Allah expiating some of his sins by it. The list goes all the way down to the smallest thing.","th":[2],"p":null,"h":{"c":"Sahih al-Bukhari","n":"5641","u":"https://sunnah.com/bukhari:5641","g":"Sahih","by":null}},{"id":"patience_whom_he_wishes_good","t":"An Unwelcome Sign","b":"The Prophet said that when Allah wants good for someone, He afflicts him. That reframes the question you are probably asking about your situation.","th":[2],"p":null,"h":{"c":"Sahih al-Bukhari","n":"5645","u":"https://sunnah.com/bukhari:5645","g":"Sahih","by":null}},{"id":"patience_greatest_trial","t":"Scaled to the Reward","b":"The Prophet said the greatest reward comes with the greatest trial, and that when Allah loves a people He tests them: whoever is content receives contentment, and whoever is displeased receives displeasure.","th":[2],"p":null,"h":{"c":"Jamiʽ at-Tirmidhi","n":"2396","u":"https://sunnah.com/tirmidhi:2396","g":"Hasan","by":"Darussalam"}},{"id":"patience_at_the_first_strike","t":"The First Hour Is the One That Counts","b":"Passing a woman weeping at a grave, the Prophet told her to fear Allah and be patient. She did not recognise him and answered sharply. When she learned who he was she came to apologise, and he said patience is at the first strike.","th":[2],"p":null,"h":{"c":"Sahih al-Bukhari","n":"1283","u":"https://sunnah.com/bukhari:1283","g":"Sahih","by":null}},{"id":"patience_what_passed_you_by","t":"It Was Never Aimed at You","b":"The Prophet taught a young companion to know that what passed him by was never going to reach him, and what reached him was never going to pass him by. Two sentences that dismantle most regret.","th":[2],"p":null,"h":{"c":"Jamiʽ at-Tirmidhi","n":"2516","u":"https://sunnah.com/tirmidhi:2516","g":"Hasan","by":"Darussalam"}},{"id":"patience_strength_in_anger","t":"A Different Definition of Strong","b":"The Prophet said the strong man is not the one who overcomes people by wrestling, but the one who controls himself when he is angry. The measurement was moved from the arms to the temper.","th":[2],"p":null,"h":{"c":"Sahih al-Bukhari","n":"6114","u":"https://sunnah.com/bukhari:6114","g":"Sahih","by":null}},{"id":"patience_do_not_say_if_only","t":"Do Not Open That Door","b":"The Prophet said to strive for what benefits you, seek the help of Allah, and not be helpless; and if something befalls you, not to say if only I had done otherwise, but to say Allah decreed and did as He willed, because if only opens the work of Satan.","th":[2],"p":null,"h":{"c":"Sahih Muslim","n":"2664","u":"https://sunnah.com/muslim:2664","g":"Sahih","by":null}},{"id":"patience_no_better_gift","t":"The Best Thing Anyone Was Given","b":"The Prophet said that whoever seeks to be patient, Allah will make him patient, and that nobody has been given a gift better or more abundant than patience. It is available by request.","th":[2],"p":null,"h":{"c":"Sahih al-Bukhari","n":"1469","u":"https://sunnah.com/bukhari:1469","g":"Sahih","by":null}},{"id":"patience_when_i_take_his_beloved","t":"One Reward, and Only One","b":"In a hadith qudsi the Prophet reported that Allah says He has no reward except Paradise for a believing servant whose beloved He takes from this world and who then bears it patiently seeking reward.","th":[2],"p":null,"h":{"c":"Sahih al-Bukhari","n":"6424","u":"https://sunnah.com/bukhari:6424","g":"Sahih","by":null}},{"id":"patience_out_hungry_home_full","t":"Out Hungry, Home Full","b":"The Prophet said that if you relied on Allah as He truly deserves, He would provide for you as He provides for the birds: they go out hungry in the morning and return full in the evening. The birds still leave the nest.","th":[2],"p":null,"h":{"c":"Jamiʽ at-Tirmidhi","n":"2344","u":"https://sunnah.com/tirmidhi:2344","g":"Hasan","by":"Darussalam"}},{"id":"patience_turned_away_at_the_door","t":"Turned Away at the Door","b":"The Prophet said that many a person, dishevelled and turned away from people’s doors, is such that if he swore by Allah, Allah would fulfil it. Closed doors among people say little about standing with Allah.","th":[2,5],"p":null,"h":{"c":"Sahih Muslim","n":"2622","u":"https://sunnah.com/muslim:2622","g":"Sahih","by":null}},{"id":"patience_she_could_not_imagine_better","t":"She Could Not Imagine Better","b":"The Prophet taught that whoever is struck by a loss and says, to Allah we belong and to Him we return, O Allah, reward me in my loss and give me better in its place, Allah gives him better. Umm Salamah said it when Abu Salamah died, unable to imagine anyone better. Allah gave her the Prophet.","th":[2,4],"p":null,"h":{"c":"Sahih Muslim","n":"918a","u":"https://sunnah.com/muslim:918a","g":"Sahih","by":null}},{"id":"patience_in_his_sight","t":"In His Sight","b":"Allah told the Prophet to wait patiently for his Lord’s decision, for he was under His eyes, and to glorify Him with praise when he rose. The patience asked of him was never a patience kept alone.","th":[2],"p":null,"q":[52,48]},{"id":"patience_when_the_chest_feels_tight","t":"When the Chest Feels Tight","b":"Allah told the Prophet that He knew his chest was tightened by what they were saying, and the verses that follow answer with glorification, praise and prostration. The distress was acknowledged before anything was asked of him.","th":[2],"p":null,"q":[15,97]},{"id":"worship_dawn_witnessed","t":"Someone Is Watching That One","b":"Establish prayer from the decline of the sun until the darkness of night, and the recitation at dawn, for the dawn recitation is witnessed. The hardest prayer to reach is the one with an audience.","th":[3],"p":null,"q":[17,78]},{"id":"worship_prayer_restrains","t":"If It Is Not Changing You","b":"Prayer restrains from immorality and wrongdoing, and the remembrance of Allah is greater. The verse assigns salah an effect outside the prayer mat. Look for the effect.","th":[3],"p":null,"q":[29,45]},{"id":"worship_seek_help","t":"Two Tools, One Verse","b":"Seek help through patience and prayer, and it is difficult except for the humbly submissive. The Quran admits it is heavy in the same sentence that recommends it.","th":[3],"p":null,"q":[2,45]},{"id":"worship_humbly_submissive","t":"The First Thing Listed","b":"The believers have succeeded, and the very first quality named is humility in their prayer. Not the length of it. The state of the heart inside it.","th":[3],"p":null,"q":[23,2]},{"id":"worship_heedless_of_prayer","t":"Heedless, Not Absent","b":"The warning is not to those who abandon prayer but to those who are heedless of it. The prayer is still being performed. That is what makes the verse uncomfortable.","th":[3],"p":null,"q":[107,5]},{"id":"worship_specified_times","t":"A Timetable, Not a Mood","b":"Prayer has been decreed upon the believers at specified times. It is not left to when you feel ready. The fixed hours are the mercy in it.","th":[3],"p":null,"q":[4,103]},{"id":"worship_leave_the_trade","t":"Leave the Trade","b":"When the call is made on the day of congregation, hurry to the remembrance of Allah and leave business. And then the verse says: that is better for you, if you only knew.","th":[3],"p":null,"q":[62,9]},{"id":"worship_sides_part_from_beds","t":"Their Sides Leave the Bed","b":"Their sides part from their beds as they call upon their Lord in fear and hope, and they spend from what We provided them. The verse describes the exact moment the blanket comes off.","th":[3],"p":null,"q":[32,16]},{"id":"worship_measured_recitation","t":"Slowly, on Purpose","b":"Recite the Quran with measured recitation. The instruction concerns pace. Nobody was ever asked to finish quickly.","th":[3],"p":null,"q":[73,4]},{"id":"worship_made_easy_for_remembrance","t":"Made Easy, and Said Four Times","b":"We have made the Quran easy to remember, so is there anyone who will take heed? The verse is repeated four times in the same surah, as though the offer needed pressing.","th":[3],"p":null,"q":[54,17]},{"id":"worship_healing_and_mercy","t":"Sent Down as a Cure","b":"We send down of the Quran that which is healing and mercy for the believers. It was described as medicine before it was described as literature.","th":[3],"p":null,"q":[17,82]},{"id":"worship_healing_in_the_breasts","t":"For What Is in the Chest","b":"Instruction has come from your Lord, and healing for what is in the breasts, and guidance and mercy. The chest is named specifically. So is the order of the four.","th":[3],"p":null,"q":[10,57]},{"id":"worship_mountain_humbled","t":"A Mountain Would Have Split","b":"Had We sent this Quran down upon a mountain, you would have seen it humbled and torn apart from fear of Allah. And these examples are presented so that people might reflect.","th":[3],"p":null,"q":[59,21]},{"id":"worship_locks_upon_hearts","t":"Or Are There Locks","b":"Do they not reflect upon the Quran, or are there locks upon their hearts? The question allows for only two explanations, and neither is flattering.","th":[3],"p":null,"q":[47,24]},{"id":"worship_reflect_upon_its_verses","t":"Sent Down to Be Thought About","b":"A blessed Book We revealed to you so that they might reflect upon its verses and so that those of understanding would be reminded. Reflection is named as the purpose, not as an optional extra.","th":[3],"p":null,"q":[38,29]},{"id":"worship_we_will_guard_it","t":"Guarded, Not Merely Preserved","b":"We sent down the Reminder, and We will be its guardian. Fourteen centuries later you are holding the same text on a phone. The claim was checkable, and it has been checked.","th":[3],"p":null,"q":[15,9]},{"id":"worship_you_we_worship","t":"The Shift Mid-Surah","b":"The opening surah praises Him in the third person, then turns and addresses Him directly: it is You we worship and You we ask for help. Seventeen times a day you stop talking about Him and start talking to Him.","th":[3],"p":null,"q":[1,5]},{"id":"worship_listen_and_be_silent","t":"Listen, and Stay Quiet","b":"When the Quran is recited, listen to it and be silent, so that you may receive mercy. The mercy is attached to the silence, which is the harder half.","th":[3],"p":null,"q":[7,204]},{"id":"worship_skins_shiver","t":"Skin First, Then Heart","b":"The skins of those who fear their Lord shiver at it, then their skins and hearts soften to the remembrance of Allah. The verse tracks a physical reaction settling into a spiritual one.","th":[3],"p":null,"q":[39,23]},{"id":"worship_created_to_worship","t":"The Stated Purpose","b":"I did not create jinn and mankind except to worship Me. Everything else you do this week is downstream of a sentence that short.","th":[3],"p":null,"q":[51,56]},{"id":"worship_sincere_to_him","t":"Sincerity Was the Command","b":"They were commanded only to worship Allah, sincere to Him in religion, upright, and to establish prayer and give zakah. Sincerity is listed as an instruction, not as a feeling that shows up on its own.","th":[3],"p":null,"q":[98,5]},{"id":"worship_prostrate_and_draw_near","t":"Get Closer","b":"Prostrate and draw near. The final verse of the first surah revealed ends with an instruction about the floor, and a promise about distance.","th":[3],"p":null,"q":[96,19]},{"id":"worship_blessed_night","t":"Sent Down in a Blessed Night","b":"We sent it down during a blessed night; We were warning. Of all the nights there have ever been, one was chosen to carry it.","th":[3],"p":null,"q":[44,3]},{"id":"worship_better_than_a_thousand","t":"Worth More Than a Lifetime","b":"The Night of Decree is better than a thousand months. Eighty-three years of worship, offered inside a single night, to people who might not get eighty-three years.","th":[3],"p":null,"q":[97,3]},{"id":"worship_bow_and_prostrate","t":"Four Verbs, No Adjectives","b":"Bow, prostrate, worship your Lord, and do good, so that you may succeed. The verse gives things to do rather than a state to reach.","th":[3],"p":null,"q":[22,77]},{"id":"worship_learn_and_teach","t":"Both Halves Named","b":"The Prophet said the best of you are those who learn the Quran and teach it. The ranking is not given to the one who only learns.","th":[3],"p":null,"h":{"c":"Sahih al-Bukhari","n":"5027","u":"https://sunnah.com/bukhari:5027","g":"Sahih","by":null}},{"id":"worship_quran_intercedes","t":"It Will Speak for You","b":"The Prophet said to recite the Quran, for it will come on the Day of Resurrection as an intercessor for its companions. The relationship is described as companionship, which takes time.","th":[3],"p":null,"h":{"c":"Sahih Muslim","n":"804","u":"https://sunnah.com/muslim:804","g":"Sahih","by":null}},{"id":"worship_a_letter_is_ten","t":"Counted by the Letter","b":"The Prophet said whoever reads a letter from the Book of Allah has a good deed for it, and each good deed is multiplied by ten, adding that alif lam mim is not one letter but three.","th":[3],"p":null,"h":{"c":"Jamiʽ at-Tirmidhi","n":"2910","u":"https://sunnah.com/tirmidhi:2910","g":"Hasan","by":"Darussalam"}},{"id":"worship_prayer_on_time","t":"Asked What He Loved Most","b":"Asked which deed is most beloved to Allah, the Prophet answered: prayer at its proper time. Then kindness to parents, then striving in the path of Allah. That was the order given.","th":[3],"p":null,"h":{"c":"Sahih al-Bukhari","n":"527","u":"https://sunnah.com/bukhari:527","g":"Sahih","by":null}},{"id":"worship_river_at_the_door","t":"Five Times in the River","b":"The Prophet asked whether any dirt would remain on a man who bathed five times a day in a river at his door. They said none. He said that is the likeness of the five prayers.","th":[3],"p":null,"h":{"c":"Sahih al-Bukhari","n":"528","u":"https://sunnah.com/bukhari:528","g":"Sahih","by":null}},{"id":"worship_expiation_between_them","t":"Cleared Between One and the Next","b":"The Prophet said the five daily prayers, and one Friday to the next, and one Ramadan to the next, expiate what falls between them so long as major sins are avoided.","th":[3],"p":null,"h":{"c":"Sahih Muslim","n":"233","u":"https://sunnah.com/muslim:233","g":"Sahih","by":null}},{"id":"worship_closest_in_prostration","t":"The Nearest Point","b":"The Prophet said the closest a servant comes to his Lord is while he is prostrating, and told people to supplicate abundantly in that position. The nearest moment is also the one with your face on the ground.","th":[3],"p":null,"h":{"c":"Sahih Muslim","n":"482","u":"https://sunnah.com/muslim:482","g":"Sahih","by":null}},{"id":"worship_last_third_of_night","t":"Every Night, the Same Offer","b":"The Prophet said that in the last third of every night Allah descends in a manner befitting Him and asks who is calling upon Him so He may answer, who is asking so He may give, who is seeking forgiveness so He may forgive.","th":[3],"p":null,"h":{"c":"Sahih al-Bukhari","n":"1145","u":"https://sunnah.com/bukhari:1145","g":"Sahih","by":null}},{"id":"worship_best_after_obligatory","t":"The Best Voluntary One","b":"The Prophet said the best fast after Ramadan is the month of Allah, Muharram, and the best prayer after the obligatory is the night prayer. Both answers point away from daylight and company.","th":[3],"p":null,"h":{"c":"Sahih Muslim","n":"1163","u":"https://sunnah.com/muslim:1163","g":"Sahih","by":null}},{"id":"worship_most_consistent","t":"Small, and Every Day","b":"The Prophet said the deeds most beloved to Allah are the most consistent, even if they are few. Asked about his own practice, Aisha said that when he did something he made it constant.","th":[3],"p":null,"h":{"c":"Sahih al-Bukhari","n":"6464","u":"https://sunnah.com/bukhari:6464","g":"Sahih","by":null}},{"id":"worship_nearer_step_by_step","t":"Nearer, Step by Step","b":"The Prophet reported that Allah said His servant draws near to Him through nothing more beloved than what He made obligatory, and keeps drawing nearer through voluntary deeds until He loves him; then if he asks, He gives him, and if he seeks refuge, He protects him.","th":[3],"p":null,"h":{"c":"Sahih al-Bukhari","n":"6502","u":"https://sunnah.com/bukhari:6502","g":"Sahih","by":null}},{"id":"worship_aim_close_and_keep_going","t":"Aim Close, and Keep Going","b":"The Prophet said that the religion is ease, and no one overburdens himself in it without being overwhelmed. So aim for what is right, come as close as you can, take good news, and draw strength from the morning, the evening and part of the night.","th":[3],"p":null,"h":{"c":"Sahih al-Bukhari","n":"39","u":"https://sunnah.com/bukhari:39","g":"Sahih","by":null}},{"id":"worship_two_rewards_for_the_struggle","t":"Two Rewards for the Struggle","b":"The Prophet said that the one skilled in the Quran is with the noble and righteous scribes, and the one who falters in it and finds it hard has two rewards. Difficulty is not a sign to stop.","th":[3],"p":null,"h":{"c":"Sahih Muslim","n":"798a","u":"https://sunnah.com/muslim:798a","g":"Sahih","by":null}},{"id":"worship_recite_what_is_easy","t":"Recite What Is Easy","b":"Knowing that some would be ill, some travelling and some striving, Allah said twice in one verse: recite what is easy of it. The same verse says that any good you send ahead you will find with Him, better and greater.","th":[3],"p":null,"q":[73,20]},{"id":"worship_has_the_time_not_come","t":"Has the Time Not Come?","b":"The verse asks the believers whether the time has not come for their hearts to be humbled at the remembrance of Allah. The very next verse speaks of the earth given life after it was dead. The question is followed by hope.","th":[3],"p":null,"q":[57,16]},{"id":"worship_a_trade_that_will_not_fail","t":"A Trade That Will Not Fail","b":"Those who recite the Book of Allah, establish prayer and give in secret and in public are described as hoping for a trade that will never perish. Reciting is the first thing in the list.","th":[3],"p":null,"q":[35,29]},{"id":"worship_constant_in_their_prayer","t":"Constant in Their Prayer","b":"The surah describes people as created anxious, impatient when harm touches them and withholding when good does. Then it names the exception: those who pray, and who keep to their prayer constantly.","th":[3,2],"p":null,"q":[70,23]},{"id":"worship_then_turn_to_your_lord","t":"Then Turn to Your Lord","b":"Right after ease is promised with hardship, the surah says: when you are free, stand up in worship, and to your Lord direct your longing. A free moment is given somewhere to go.","th":[3],"p":null,"q":[94,8]},{"id":"worship_not_sent_to_distress_you","t":"Not Sent to Distress You","b":"Surah Ta Ha opens by telling the Prophet that the Quran was not sent down to make him distressed, but as a reminder for those who fear Allah. It came to remind, not to wear down.","th":[3],"p":null,"q":[20,2]},{"id":"dua_good_in_both","t":"The Dua He Made Most","b":"Good in this world, good in the Hereafter, and protection from the Fire. The Prophet said this more than any other supplication, and it asks for nothing specific at all.","th":[4],"p":null,"q":[2,201]},{"id":"dua_do_not_let_hearts_deviate","t":"Guidance Can Be Lost","b":"Our Lord, do not let our hearts deviate after You have guided us, and grant us mercy from Yourself. The people making this dua were already guided. That is exactly why they made it.","th":[4],"p":null,"q":[3,8]},{"id":"dua_we_have_believed","t":"Belief First, Then the Request","b":"Our Lord, we have believed, so forgive us our sins and protect us from the punishment of the Fire. The claim is placed before the ask, which is how the Quran teaches people to open.","th":[4],"p":null,"q":[3,16]},{"id":"dua_our_excesses","t":"They Named Their Own Failures","b":"Facing an enemy, they asked forgiveness for their sins and for their excesses in their affair, then asked for firm feet and victory. They started with what was wrong with them, not with the enemy.","th":[4],"p":null,"q":[3,147]},{"id":"dua_not_created_in_vain","t":"A Prayer Made While Thinking","b":"Those who remember Allah standing, sitting and lying on their sides, and reflect on the creation of the heavens and the earth, say: our Lord, You did not create this without purpose. Reflection ended in a supplication.","th":[4],"p":null,"q":[3,191]},{"id":"dua_die_with_the_righteous","t":"Take Us With the Righteous","b":"Our Lord, forgive us our sins, remove from us our misdeeds, and cause us to die among the righteous. The last request is about company, at the one moment you cannot arrange it yourself.","th":[4],"p":null,"q":[3,193]},{"id":"dua_pour_upon_us_patience","t":"Pour It Over Us","b":"Threatened with execution for believing, the magicians of Pharaoh asked Allah to pour patience upon them and take them as Muslims. They did not ask to be spared. They asked to be able to bear it.","th":[4],"p":null,"q":[7,126]},{"id":"dua_forgive_my_parents","t":"Include Them","b":"Our Lord, forgive me and my parents and the believers on the Day the account is established. He asked for three parties, and only one of them was himself.","th":[4],"p":null,"q":[14,41]},{"id":"dua_mercy_and_right_guidance","t":"Said by Young People in a Cave","b":"Our Lord, grant us mercy from Yourself and prepare for us right guidance in our affair. They were hiding from a state that wanted them dead, and what they asked for was direction.","th":[4],"p":null,"q":[18,10]},{"id":"dua_comfort_of_our_eyes","t":"A Prayer for the People You Live With","b":"Our Lord, grant us from among our spouses and offspring comfort to our eyes, and make us leaders for the righteous. Family peace is asked for here as a religious request, not a private one.","th":[4],"p":null,"q":[25,74]},{"id":"dua_best_of_the_merciful","t":"The Last Verse of the Surah","b":"My Lord, forgive and have mercy, and You are the best of those who show mercy. A whole surah about the successful believers closes by asking for forgiveness anyway.","th":[4],"p":null,"q":[23,118]},{"id":"dua_hearts_find_rest","t":"Where the Rest Is Kept","b":"In the remembrance of Allah hearts find rest. Not distraction, not resolution of the problem. Rest, located precisely.","th":[4],"p":null,"q":[13,28]},{"id":"dua_remember_much","t":"The Only Worship Given No Limit","b":"Believers are told to remember Allah with much remembrance. Every other act of worship in the Quran arrives with a measure attached. This one is told to be abundant.","th":[4],"p":null,"q":[33,41]},{"id":"dua_remember_me","t":"A Trade With Terms","b":"Remember Me, and I will remember you; be grateful to Me and do not deny Me. Whatever you say quietly this afternoon is answered somewhere far above the room.","th":[4],"p":null,"q":[2,152]},{"id":"dua_within_yourself","t":"Quietly, and in the Morning","b":"Remember your Lord within yourself, humbly and in fear, without loudness in speech, in the mornings and evenings. The instruction specifies volume, posture and time.","th":[4],"p":null,"q":[7,205]},{"id":"dhikr_subhanallah_hundred","t":"Foam of the Sea","b":"The Prophet said whoever says SubhanAllahi wa bihamdih a hundred times in a day has his sins wiped away, even if they were like the foam of the sea. The arithmetic is not in your favour anywhere else.","th":[4],"p":null,"h":{"c":"Sahih al-Bukhari","n":"6405","u":"https://sunnah.com/bukhari:6405","g":"Sahih","by":null}},{"id":"dhikr_two_light_words","t":"Light on the Tongue, Heavy on the Scale","b":"The Prophet named two phrases light on the tongue, heavy on the scale, beloved to the Most Merciful: SubhanAllahi wa bihamdih, SubhanAllahil-Azim. Nothing else is described that way.","th":[4],"p":null,"h":{"c":"Sahih al-Bukhari","n":"6682","u":"https://sunnah.com/bukhari:6682","g":"Sahih","by":null}},{"id":"dhikr_four_most_beloved","t":"The Four He Named","b":"The Prophet said the most beloved speech to Allah is four phrases, and that it does not matter which of them you begin with: SubhanAllah, alhamdulillah, la ilaha illallah, Allahu akbar.","th":[4],"p":null,"h":{"c":"Sahih Muslim","n":"2695","u":"https://sunnah.com/muslim:2695","g":"Sahih","by":null}},{"id":"dhikr_sayyid_al_istighfar","t":"The Master of Seeking Forgiveness","b":"The Prophet taught a supplication he called the master of seeking forgiveness, in which the servant acknowledges the covenant, admits the sin and asks for pardon, and said that whoever says it with certainty by day and dies that day enters Paradise.","th":[4],"p":null,"h":{"c":"Sahih al-Bukhari","n":"6306","u":"https://sunnah.com/bukhari:6306","g":"Sahih","by":null}},{"id":"dhikr_living_and_dead","t":"The Living and the Dead","b":"The Prophet compared the one who remembers his Lord and the one who does not to the living and the dead. The difference was not described as a matter of degree.","th":[4],"p":null,"h":{"c":"Sahih al-Bukhari","n":"6407","u":"https://sunnah.com/bukhari:6407","g":"Sahih","by":null}},{"id":"dhikr_gatherings_surrounded","t":"Who Else Is in the Room","b":"The Prophet said that no people gather in a house of Allah reciting His Book and studying it among themselves except that tranquillity descends upon them, mercy covers them, angels surround them, and Allah mentions them to those with Him.","th":[4],"p":null,"h":{"c":"Sahih Muslim","n":"2699","u":"https://sunnah.com/muslim:2699","g":"Sahih","by":null}},{"id":"dhikr_when_he_remembers_me","t":"Mentioned in a Better Assembly","b":"In a hadith qudsi the Prophet reported that Allah says He is with His servant when he remembers Him: if he mentions Him to himself, He mentions him to Himself, and if he mentions Him in a gathering, He mentions him in a better gathering.","th":[4],"p":null,"h":{"c":"Sahih al-Bukhari","n":"7405","u":"https://sunnah.com/bukhari:7405","g":"Sahih","by":null}},{"id":"dua_not_hasty","t":"The Only Way to Lose It","b":"The Prophet said the supplication of a servant is answered as long as he does not become impatient and say that he supplicated and was not answered. Nothing else on the list disqualifies you.","th":[4],"p":null,"h":{"c":"Sahih Muslim","n":"2735","u":"https://sunnah.com/muslim:2735","g":"Sahih","by":null}},{"id":"dhikr_words_of_refuge","t":"Words for an Unfamiliar Place","b":"The Prophet said whoever stops somewhere and says that he seeks refuge in the perfect words of Allah from the evil of what He created, nothing will harm him until he moves on from that place.","th":[4],"p":null,"h":{"c":"Sahih Muslim","n":"2708","u":"https://sunnah.com/muslim:2708","g":"Sahih","by":null}},{"id":"dhikr_la_ilaha_hundred","t":"A Hundred, and a Shield","b":"The Prophet said whoever declares the oneness of Allah in the full formula a hundred times a day receives the reward of freeing ten slaves, has a hundred good deeds written and a hundred sins erased, and is guarded from Satan until evening.","th":[4],"p":null,"h":{"c":"Sahih Muslim","n":"2691","u":"https://sunnah.com/muslim:2691","g":"Sahih","by":null}},{"id":"dua_abu_bakr_in_prayer","t":"What He Taught Abu Bakr to Say","b":"Abu Bakr asked for a supplication to say in his prayer, and was taught to say that he had wronged himself greatly, that none forgives sins but Allah, and to ask for forgiveness and mercy from Him directly.","th":[4],"p":null,"h":{"c":"Sahih al-Bukhari","n":"834","u":"https://sunnah.com/bukhari:834","g":"Sahih","by":null}},{"id":"dhikr_after_the_prayer","t":"Thirty-Three at a Time","b":"When the poor companions worried that the wealthy had overtaken them in reward, the Prophet taught them to glorify, praise and magnify Allah thirty-three times after every prayer. The gap closed with words.","th":[4],"p":null,"h":{"c":"Sahih al-Bukhari","n":"843","u":"https://sunnah.com/bukhari:843","g":"Sahih","by":null}},{"id":"dhikr_treasure_of_paradise","t":"A Treasure You Can Say","b":"The Prophet told a companion to say that there is no might and no power except with Allah, and called it a treasure from the treasures of Paradise. It costs a breath.","th":[4],"p":null,"h":{"c":"Sahih Muslim","n":"2704","u":"https://sunnah.com/muslim:2704","g":"Sahih","by":null}},{"id":"dhikr_juwayriyah","t":"Four Phrases, Weighed","b":"Finding Juwayriyah still sitting in dhikr hours after he left her, the Prophet said he had said four phrases three times that would outweigh everything she had said since morning: glory to Allah and praise, by the number of His creation, the pleasure of Himself, the weight of His Throne and the ink of His words.","th":[4],"p":null,"h":{"c":"Sahih Muslim","n":"2726","u":"https://sunnah.com/muslim:2726","g":"Sahih","by":null}},{"id":"dhikr_three_quls_at_night","t":"The Last Thing Before Sleep","b":"Every night the Prophet would cup his hands, recite al-Ikhlas, al-Falaq and an-Nas into them, and wipe over as much of his body as he could reach, beginning with his head and face. He did this three times.","th":[4],"p":null,"h":{"c":"Sahih al-Bukhari","n":"5017","u":"https://sunnah.com/bukhari:5017","g":"Sahih","by":null}},{"id":"dua_granted_or_turned_away","t":"Granted, or Something Turned Away","b":"The Prophet said that no Muslim on earth asks Allah for anything, so long as it is not sinful and does not cut family ties, without Allah granting it or turning away a harm of its measure. When the companions said they would ask more, he said Allah has more.","th":[4],"p":null,"h":{"c":"Jamiʽ at-Tirmidhi","n":"3573","u":"https://sunnah.com/tirmidhi:3573","g":"Hasan","by":"Darussalam"}},{"id":"dua_no_rancour_in_our_hearts","t":"No Rancour in Our Hearts","b":"Those who came later are described praying for the believers before them: forgive us and our brothers who preceded us in faith, and put no rancour in our hearts toward those who believe. A clean heart is something you can ask for.","th":[4,5],"p":null,"q":[59,10]},{"id":"character_do_not_say_uff","t":"Not Even That Sound","b":"Placed immediately after the command to worship none but Him is the command about parents: do not say even a word of irritation to them, and do not repel them. The bar was set at a syllable.","th":[5],"p":null,"q":[17,23]},{"id":"character_wing_of_humility","t":"Lower the Wing","b":"Lower to them the wing of humility out of mercy, and say: my Lord, have mercy upon them as they raised me when I was small. A supplication for them was written into the command about them.","th":[5],"p":null,"q":[17,24]},{"id":"character_carried_and_weaned","t":"The Cost Was Itemised","b":"We enjoined upon man care for his parents, and then named what his mother bore: weakness upon weakness, and two years of weaning. Be grateful to Me and to your parents. The gratitude was not left generic.","th":[5],"p":null,"q":[31,14]},{"id":"character_thirty_and_forty","t":"The Prayer of a Grown Child","b":"At forty, he says: my Lord, enable me to be grateful for the favour You bestowed on me and on my parents, and to do righteousness that pleases You, and make my offspring righteous. Three generations in one supplication.","th":[5],"p":null,"q":[46,15]},{"id":"character_worship_and_parents","t":"Then the Whole Street","b":"Worship Allah, associate nothing with Him, and be good to parents, relatives, orphans, the needy, the near neighbour, the distant neighbour, the companion at your side, the traveller, and those your right hands possess. The list keeps widening.","th":[5],"p":null,"q":[4,36]},{"id":"character_most_noble","t":"The Only Ranking He Recognises","b":"We made you into peoples and tribes so that you may know one another. The most noble of you in the sight of Allah is the most righteous of you. Every other league table is your own invention.","th":[5],"p":null,"q":[49,13]},{"id":"character_avoid_suspicion","t":"Three Things in One Verse","b":"Avoid much assumption, because some assumption is sin; do not spy; and do not backbite one another. Then the verse asks whether you would eat the flesh of your dead brother.","th":[5],"p":null,"q":[49,12]},{"id":"character_believers_are_brothers","t":"Then Go and Fix It","b":"The believers are but brothers, so make peace between your brothers. The statement of relationship arrives with an obligation attached to it in the same sentence.","th":[5],"p":null,"q":[49,10]},{"id":"character_affection_and_mercy","t":"Placed Between You","b":"Among His signs is that He created spouses for you so that you may find rest in them, and placed between you affection and mercy. The feeling is described as something He put there, not something you generated.","th":[5],"p":null,"q":[30,21]},{"id":"character_best_nation","t":"What the Title Was For","b":"You are the best nation brought forth for people: you enjoin what is right, forbid what is wrong, and believe in Allah. The description is followed immediately by the work that earns it.","th":[5],"p":null,"q":[3,110]},{"id":"character_restrain_anger","t":"Restrain, Then Pardon","b":"Those who spend in ease and in hardship, who restrain anger, and who pardon people. And Allah loves the doers of good. Two of the three qualities are about what you do not do.","th":[5],"p":null,"q":[3,134]},{"id":"character_repel_with_better","t":"Answer It Better","b":"Repel evil with what is better, and the one between you and whom there is enmity will become as though he were a devoted friend. The verse promises an outcome most people never test.","th":[5],"p":null,"q":[41,34]},{"id":"character_walk_gently","t":"How They Walk","b":"The servants of the Most Merciful walk upon the earth gently, and when the ignorant address them, they say words of peace. The description begins with their footsteps and ends with their replies.","th":[5],"p":null,"q":[25,63]},{"id":"character_the_steep_path","t":"The Uphill Road","b":"What is the steep path? Freeing a slave, or feeding on a day of severe hunger an orphan of near relationship or a needy person in misery. The Quran defines the difficult road as feeding someone.","th":[5],"p":null,"q":[90,14]},{"id":"character_in_spite_of_love","t":"While They Still Wanted It","b":"They give food, in spite of loving it, to the needy, the orphan and the captive. The verse does not say they had spare food. It says they gave what they wanted.","th":[5],"p":null,"q":[76,8]},{"id":"character_one_body","t":"One Body, One Fever","b":"The Prophet said the believers in their mutual mercy, love and compassion are like one body: when one limb complains, the rest of the body responds with sleeplessness and fever. Not sympathy. Fever.","th":[5],"p":null,"h":{"c":"Sahih al-Bukhari","n":"6011","u":"https://sunnah.com/bukhari:6011","g":"Sahih","by":null}},{"id":"character_love_for_your_brother","t":"The Thirteenth Hadith","b":"The Prophet said none of you believes until he loves for his brother what he loves for himself. It sits near the very start of Sahih al-Bukhari, which tells you where it was placed in importance.","th":[5],"p":null,"h":{"c":"Sahih al-Bukhari","n":"13","u":"https://sunnah.com/bukhari:13","g":"Sahih","by":null}},{"id":"character_best_to_his_family","t":"Measured at Home","b":"The Prophet said the best of you are the best to their families, and that he was the best of them to his family. The test of character was placed inside the house.","th":[5],"p":null,"h":{"c":"Jamiʽ at-Tirmidhi","n":"3895","u":"https://sunnah.com/tirmidhi:3895","g":"Sahih","by":"Darussalam"}},{"id":"character_your_mother_three_times","t":"Asked Four Times","b":"A man asked who deserved his good companionship most. Your mother, he said. Then who? Your mother. Then who? Your mother. Then who? Then your father. The repetition was the answer.","th":[5],"p":null,"h":{"c":"Sahih al-Bukhari","n":"5971","u":"https://sunnah.com/bukhari:5971","g":"Sahih","by":null}},{"id":"character_ties_of_kinship","t":"Provision, Through People","b":"The Prophet said whoever would like his provision to be expanded and his term to be extended should maintain his ties of kinship. The relative you have not called is listed under rizq.","th":[5],"p":null,"h":{"c":"Sahih al-Bukhari","n":"5985","u":"https://sunnah.com/bukhari:5985","g":"Sahih","by":null}},{"id":"character_speak_good_or_be_silent","t":"Three Clauses, One Belief","b":"Whoever believes in Allah and the Last Day, let him speak good or stay silent; and let him honour his neighbour; and let him honour his guest. Each duty was tied to the same declaration of faith.","th":[5],"p":null,"h":{"c":"Sahih al-Bukhari","n":"6018","u":"https://sunnah.com/bukhari:6018","g":"Sahih","by":null}},{"id":"character_he_looks_at_hearts","t":"Not at Your Forms","b":"The Prophet said Allah does not look at your bodies or your appearances, but looks at your hearts and your deeds, and then said that a Muslim is sacred to another Muslim in his blood, his property and his honour.","th":[5],"p":null,"h":{"c":"Sahih Muslim","n":"2564","u":"https://sunnah.com/muslim:2564","g":"Sahih","by":null}},{"id":"character_heaviest_on_the_scale","t":"Heavier Than Anything Else","b":"The Prophet said that nothing will be heavier on the believer’s Scale on the Day of Resurrection than good character, and that Allah detests the one who is obscene and coarse in speech.","th":[5],"p":null,"h":{"c":"Jamiʽ at-Tirmidhi","n":"2002","u":"https://sunnah.com/tirmidhi:2002","g":"Sahih","by":"Darussalam"}},{"id":"character_charity_does_not_decrease","t":"Three Things That Reverse","b":"Charity does not decrease wealth. Allah increases in honour the one who pardons. And nobody humbles himself for Allah except that Allah raises him. Each promise runs the opposite way to instinct.","th":[5],"p":null,"h":{"c":"Sahih Muslim","n":"2588","u":"https://sunnah.com/muslim:2588","g":"Sahih","by":null}},{"id":"character_relieve_a_hardship","t":"Whoever Covers, Is Covered","b":"The Prophet said that whoever relieves a Muslim of a hardship in this world, Allah will relieve him of a hardship on the Day of Resurrection, and whoever conceals the fault of a Muslim, Allah will conceal his.","th":[5],"p":null,"h":{"c":"Sahih al-Bukhari","n":"2442","u":"https://sunnah.com/bukhari:2442","g":"Sahih","by":null}},{"id":"character_shown_mercy_by_the_merciful","t":"Mercy Passed Along","b":"The Prophet said that the merciful are shown mercy by the Most Merciful: be merciful to those on the earth, and the One above the heavens will be merciful to you. The mercy you hope for is the mercy you are asked to give.","th":[5,1],"p":null,"h":{"c":"Jamiʽ at-Tirmidhi","n":"1924","u":"https://sunnah.com/tirmidhi:1924","g":"Hasan","by":"Darussalam"}},{"id":"character_your_smile_is_charity","t":"Charity Without a Purse","b":"The Prophet counted your smile at your brother as charity, and so too guiding someone who is lost, helping a person who cannot see well, moving a stone or a thorn from the road, and pouring from your bucket into his. Most of it costs only attention.","th":[5],"p":null,"h":{"c":"Jamiʽ at-Tirmidhi","n":"1956","u":"https://sunnah.com/tirmidhi:1956","g":"Hasan","by":"Darussalam"}},{"id":"character_best_to_the_one_beside_you","t":"Best to the One Beside You","b":"The Prophet said that the best companion in the sight of Allah is the one who is best to his companion, and the best neighbour is the one who is best to his neighbour. The people closest to you are where it is measured.","th":[5],"p":null,"h":{"c":"Jamiʽ at-Tirmidhi","n":"1944","u":"https://sunnah.com/tirmidhi:1944","g":"Sahih","by":"Darussalam"}},{"id":"character_the_first_words_he_heard","t":"The First Words He Heard","b":"When the Prophet reached Madinah, Abdullah ibn Salam looked at his face and knew it was not the face of a liar. The first words he heard from him: spread salam, feed people, and pray while others sleep, and you will enter Paradise in peace.","th":[5,3],"p":null,"h":{"c":"Jamiʽ at-Tirmidhi","n":"2485","u":"https://sunnah.com/tirmidhi:2485","g":"Sahih","by":"Darussalam"}},{"id":"character_the_young_and_the_old","t":"The Young and the Old","b":"The Prophet said that whoever does not show mercy to our young and does not recognise the honour of our elders is not one of us. Belonging is described as tenderness in one direction and respect in the other.","th":[5,1],"p":null,"h":{"c":"Jamiʽ at-Tirmidhi","n":"1920","u":"https://sunnah.com/tirmidhi:1920","g":"Hasan","by":"Darussalam"}},{"id":"character_a_date_that_grows","t":"A Date That Grows Into a Mountain","b":"The Prophet said that when someone gives the worth of a single date in charity from honest earnings, Allah accepts it and raises it for him, as one of you raises a young foal, until it becomes like a mountain.","th":[5,7],"p":null,"h":{"c":"Sahih al-Bukhari","n":"1410","u":"https://sunnah.com/bukhari:1410","g":"Sahih","by":null}},{"id":"character_the_better_of_the_two","t":"The Better of the Two","b":"The Prophet said it is not lawful to cut off a brother for more than three nights, each turning away when they meet, and that the better of the two is the one who greets first. A salam is often the way back.","th":[5],"p":null,"h":{"c":"Sahih al-Bukhari","n":"6077","u":"https://sunnah.com/bukhari:6077","g":"Sahih","by":null}},{"id":"character_deprived_of_gentleness","t":"Deprived of Gentleness","b":"The Prophet said that whoever is deprived of gentleness is deprived of good. A short sentence with a long reach: into how we speak, how we correct, how we wait and how we answer.","th":[5],"p":null,"h":{"c":"Sahih Muslim","n":"2592a","u":"https://sunnah.com/muslim:2592a","g":"Sahih","by":null}},{"id":"character_given_where_no_one_sees","t":"Given Where No One Sees","b":"Giving openly is good, the verse says, but giving quietly to those in need is better for you, and through it Allah removes some of your misdeeds. He is aware of what you do, even when no one else is.","th":[5],"p":null,"q":[2,271]},{"id":"character_a_kind_word_comes_first","t":"A Kind Word Comes First","b":"A kind word and forgiveness, the verse says, are better than charity followed by hurt, and Allah is free of need and forbearing. Sometimes the gift is in how it is given, and in what is left unsaid.","th":[5],"p":null,"q":[2,263]},{"id":"character_say_what_is_best","t":"Say What Is Best","b":"Allah tells His servants to say what is best, because Shaytan sows discord between people. Not only what is true, and not only what is allowed, but what is best.","th":[5],"p":null,"q":[17,53]},{"id":"character_return_it_with_better","t":"Return It With Better","b":"When you are greeted, the verse says, greet back with something better, or at least return it, for Allah keeps account of all things. Even a salam is counted.","th":[5],"p":null,"q":[4,86]},{"id":"hereafter_every_soul_tastes","t":"Then You Are Paid in Full","b":"Every soul will taste death, and you will only be given your full compensation on the Day of Resurrection. Nothing settles here. This is not where the accounts close.","th":[6],"p":null,"q":[3,185]},{"id":"hereafter_created_death_and_life","t":"Death Was Created Too","b":"He created death and life to test which of you is best in deed. Death is named first, and described as something made on purpose rather than as an accident at the end.","th":[6],"p":null,"q":[67,2]},{"id":"hereafter_then_returned","t":"The Direction of Travel","b":"Every soul will taste death, then to Us you will be returned. The verse gives the destination in the same breath as the departure.","th":[6],"p":null,"q":[29,57]},{"id":"hereafter_it_will_meet_you","t":"It Is Coming to Find You","b":"Say: the death you flee from will certainly meet you, then you will be returned to the Knower of the unseen and the witnessed. Avoidance was addressed directly, and dismissed.","th":[6],"p":null,"q":[62,8]},{"id":"hereafter_if_only_you_would_delay","t":"The Request That Comes Too Late","b":"Spend from what We have provided before death comes to one of you and he says: my Lord, if only You would delay me for a brief term so I could give charity. The Quran records the request and the moment it becomes impossible.","th":[6],"p":null,"q":[63,10]},{"id":"hereafter_atom_of_good","t":"Down to an Atom","b":"Whoever does an atom's weight of good will see it, and whoever does an atom's weight of evil will see it. Nothing was ever too small to record, in either direction.","th":[6],"p":null,"q":[99,7]},{"id":"hereafter_the_scales","t":"Weighed, Not Counted","b":"As for one whose scales are heavy, he will be in a pleasant life. The measurement is by weight, and weight is not the same as quantity.","th":[6],"p":null,"q":[101,6]},{"id":"hereafter_no_soul_possesses","t":"Nobody Can Cover for You","b":"The Day when no soul will possess anything for another soul, and the command that Day belongs entirely to Allah. Every arrangement you rely on now is described as absent then.","th":[6],"p":null,"q":[82,19]},{"id":"hereafter_sound_heart","t":"The Only Thing You Carry","b":"The Day when neither wealth nor children will benefit, except the one who comes to Allah with a sound heart. One item passes through, and it is not on any inventory.","th":[6],"p":null,"q":[26,89]},{"id":"hereafter_reassured_soul","t":"Called by Name","b":"O reassured soul, return to your Lord, well pleased and pleasing to Him. Enter among My servants and enter My Paradise. Four sentences, and every one of them is an invitation.","th":[6],"p":null,"q":[89,27]},{"id":"hereafter_closer_than_jugular","t":"Closer Than Your Own Pulse","b":"We created man and know what his soul whispers to him, and We are closer to him than his jugular vein. The whispering is included. Nothing is being missed.","th":[6],"p":null,"q":[50,16]},{"id":"hereafter_amusement_and_diversion","t":"Read the Description","b":"The life of this world is amusement, diversion, adornment, boasting among yourselves, and competition in wealth and children. Then the verse compares it to rain that pleases the farmers before it withers.","th":[6],"p":null,"q":[57,20]},{"id":"hereafter_you_prefer_this_life","t":"But You Prefer","b":"You prefer the worldly life, while the Hereafter is better and more lasting. The verse does not accuse anyone of disbelief. It accuses them of preference.","th":[6],"p":null,"q":[87,16]},{"id":"hereafter_enduring_good_deeds","t":"Adornment, and Then What Lasts","b":"Wealth and children are the adornment of the worldly life, but the enduring righteous deeds are better with your Lord for reward and better for hope. Both halves are true at once.","th":[6],"p":null,"q":[18,46]},{"id":"hereafter_everyone_will_perish","t":"Everything on It","b":"Everyone upon the earth will perish, and there will remain the Face of your Lord, Owner of Majesty and Honour. The verse empties the room and then names who is left.","th":[6],"p":null,"q":[55,26]},{"id":"hereafter_home_of_settlement","t":"Passing Through","b":"This worldly life is only temporary enjoyment, and the Hereafter is the home of settlement. One of those two words describes where you unpack.","th":[6],"p":null,"q":[40,39]},{"id":"hereafter_three_follow","t":"Two Come Back","b":"The Prophet said three things follow a person to the grave: his family, his wealth and his deeds. Two of them return, and one stays with him.","th":[6],"p":null,"h":{"c":"Sahih al-Bukhari","n":"6514","u":"https://sunnah.com/bukhari:6514","g":"Sahih","by":null}},{"id":"hereafter_stranger_or_traveller","t":"A Stranger, or Passing Through","b":"The Prophet took hold of a companion's shoulders and told him to be in this world as though he were a stranger or a traveller. Ibn Umar used to add: when evening comes, do not expect the morning.","th":[6],"p":null,"h":{"c":"Sahih al-Bukhari","n":"6416","u":"https://sunnah.com/bukhari:6416","g":"Sahih","by":null}},{"id":"hereafter_three_that_continue","t":"Three Things Keep Working","b":"The Prophet said that when a person dies his deeds come to an end except three: an ongoing charity, knowledge that is benefited from, and a righteous child who prays for him. Some work outlives the worker.","th":[6],"p":null,"h":{"c":"Sahih Muslim","n":"1631","u":"https://sunnah.com/muslim:1631","g":"Sahih","by":null}},{"id":"hereafter_surrounded_by_hardship","t":"What Each One Is Fenced With","b":"The Prophet said Paradise is surrounded by hardships and the Fire is surrounded by desires. Neither is reached accidentally, and the easier approach is the wrong one.","th":[6],"p":null,"h":{"c":"Sahih Muslim","n":"2822","u":"https://sunnah.com/muslim:2822","g":"Sahih","by":null}},{"id":"gratitude_if_you_are_grateful","t":"The Increase Is Promised","b":"If you are grateful, I will surely increase you. The verse states the consequence as a certainty and does not say what the increase will be made of.","th":[7],"p":null,"q":[14,7]},{"id":"gratitude_cannot_enumerate","t":"You Could Not Finish Counting","b":"If you tried to count the favours of Allah, you could never number them. Start with the fact that you are reading, breathing, and able to understand this sentence.","th":[7],"p":null,"q":[16,18]},{"id":"gratitude_for_himself","t":"It Was Always for You","b":"Whoever is grateful is grateful for the benefit of himself, and whoever is ungrateful, then Allah is Free of need, Praiseworthy. Gratitude was never something He required from you.","th":[7],"p":null,"q":[31,12]},{"id":"gratitude_which_favours","t":"Asked Thirty-One Times","b":"So which of the favours of your Lord would you deny? The question is repeated through the whole surah, after mercy, after creation, after provision, until refusing to answer becomes the answer.","th":[7],"p":null,"q":[55,13]},{"id":"gratitude_provision_guaranteed","t":"Every Creature Is on the List","b":"There is no creature on the earth whose provision is not upon Allah, and He knows its dwelling place and its place of storage. The guarantee is not narrowed to people.","th":[7],"p":null,"q":[11,6]},{"id":"gratitude_creatures_carry_nothing","t":"They Carry No Stores","b":"How many creatures carry no provision of their own; Allah provides for them and for you. The verse compares your anxiety to a bird that has never once planned ahead.","th":[7],"p":null,"q":[29,60]},{"id":"gratitude_he_compensates_it","t":"It Comes Back","b":"Whatever you spend of anything, He will replace it, and He is the best of providers. The verse describes spending as a transfer rather than a loss.","th":[7],"p":null,"q":[34,39]},{"id":"gratitude_report_the_favour","t":"Say It Out Loud","b":"And as for the favour of your Lord, speak of it. Right after being told about the orphan and the one who asks, the instruction is to talk about what you were given.","th":[7],"p":null,"q":[93,11]},{"id":"gratitude_al_kawthar","t":"Given Abundance","b":"We have granted you abundance. Three verses long, revealed to a man who had just been mocked as cut off, and it opens by telling him what he actually has.","th":[7],"p":null,"q":[108,1]},{"id":"gratitude_look_at_the_camels","t":"Look at the Camels","b":"Do they not look at the camels, how they were created, and at the sky, how it was raised, and at the mountains, and at the earth? The invitation is to notice ordinary things properly.","th":[7],"p":null,"q":[88,17]},{"id":"gratitude_bitter_water","t":"It Could Have Been Bitter","b":"Have you considered the water you drink? If We willed We could make it bitter, so why are you not grateful? The whole argument is made with a glass of water.","th":[7],"p":null,"q":[56,70]},{"id":"gratitude_pleased_by_praise","t":"He Is Pleased by a Sentence","b":"The Prophet said that Allah is pleased with a servant who eats a meal and praises Him for it, or drinks a drink and praises Him for it. The pleasure of your Lord is attached to a sentence said after a meal.","th":[7],"p":null,"h":{"c":"Sahih Muslim","n":"2734a","u":"https://sunnah.com/muslim:2734a","g":"Sahih","by":null}},{"id":"gratitude_richness_of_the_soul","t":"Where Wealth Is Kept","b":"The Prophet said that richness is not an abundance of possessions, but that richness is the richness of the soul. The definition was moved out of the account and into the person.","th":[7],"p":null,"h":{"c":"Sahih al-Bukhari","n":"6446","u":"https://sunnah.com/bukhari:6446","g":"Sahih","by":null}},{"id":"gratitude_whoever_wakes_secure","t":"Three Things, and the Whole World","b":"The Prophet said that whoever wakes secure in his household, healthy in his body, with enough food for his day, it is as though the whole world has been gathered for him. Check the list against your morning.","th":[7],"p":null,"h":{"c":"Jamiʽ at-Tirmidhi","n":"2346","u":"https://sunnah.com/tirmidhi:2346","g":"Hasan","by":"Darussalam"}},{"id":"gratitude_two_blessings","t":"The Two Most People Waste","b":"The Prophet said there are two blessings in which many people are deceived: good health, and free time. Both are being spent right now, whether or not you decided how.","th":[7],"p":null,"h":{"c":"Sahih al-Bukhari","n":"6412","u":"https://sunnah.com/bukhari:6412","g":"Sahih","by":null}},{"id":"gratitude_thanks_that_begins_with_people","t":"Thanks That Begins With People","b":"The Prophet said that whoever does not thank people does not thank Allah. Gratitude to Him is not kept apart from the people through whom His gifts arrive.","th":[7,5],"p":null,"h":{"c":"Jamiʽ at-Tirmidhi","n":"1954","u":"https://sunnah.com/tirmidhi:1954","g":"Sahih","by":"Darussalam"}},{"id":"gratitude_the_best_remembrance","t":"The Best Remembrance, the Best Asking","b":"The Prophet said that the best remembrance is la ilaha illallah, and the best supplication is alhamdulillah. Two short phrases, ready at any moment of the day.","th":[7,4],"p":null,"h":{"c":"Jamiʽ at-Tirmidhi","n":"3383","u":"https://sunnah.com/tirmidhi:3383","g":"Hasan","by":"Darussalam"}},{"id":"gratitude_where_to_rest_your_eyes","t":"Where to Rest Your Eyes","b":"The Prophet said to look at those below you and not at those above you, because that is more likely to keep you from belittling the blessings Allah has given you. Comparison can feed gratitude or starve it.","th":[7],"p":null,"h":{"c":"Sahih Muslim","n":"2963c","u":"https://sunnah.com/muslim:2963c","g":"Sahih","by":null}}]};
